// ─── SANITIZE ─────────────────────────────────────────────────────────────────
// Also normalizes legacy account fields for backward compatibility:
//   disabled → is_active (inverted), includeInNetWorth → include_in_networth
function sanitizeAccount(a) {
  if (!a || typeof a !== "object") return a;
  const out = { ...a };
  // Normalize is_active from legacy `disabled` field
  if (out.is_active === undefined) {
    out.is_active = out.disabled === true ? false : true;
  }
  // Keep disabled in sync for backward compat
  out.disabled = !out.is_active;
  // Normalize include_in_networth — always resolve from whichever field the payload set,
  // giving priority to include_in_networth if both differ, else fall back to includeInNetWorth.
  // Critical: never let a stale include_in_networth override a freshly toggled includeInNetWorth.
  if (out.include_in_networth !== undefined) {
    out.includeInNetWorth = out.include_in_networth;          // DB field wins if present
  } else if (out.includeInNetWorth !== undefined) {
    out.include_in_networth = out.includeInNetWorth;          // legacy field wins if only one set
  } else {
    out.include_in_networth = true;                           // default: include
    out.includeInNetWorth   = true;
  }
  // Normalize account_type from legacy categoryId
  if (out.account_type === undefined && out.categoryId !== undefined) {
    out.account_type = out.categoryId;
  }
  if (out.categoryId === undefined && out.account_type !== undefined) {
    out.categoryId = out.account_type;
  }
  return out;
}

function sanitize(raw) {
  if (!raw || typeof raw !== "object") return { ...DEFAULT };
  return {
    accounts:            Array.isArray(raw.accounts)            ? raw.accounts.map(sanitizeAccount) : [],
    accountCategories:   (() => {
                           const knownInv = new Set(["cat_broker","cat_mf","cat_invest"]);
                           const cats = Array.isArray(raw.accountCategories) ? raw.accountCategories
                                      : Array.isArray(raw.categories)        ? raw.categories
                                      : DEFAULT.accountCategories;
                           // Backfill isInvestmentType for known IDs in case old data lacked the flag
                           return cats.map(c => knownInv.has(c.id) ? {...c, isInvestmentType:true} : c);
                         })(),
    expenseCategories:   Array.isArray(raw.expenseCategories)   ? raw.expenseCategories  : DEFAULT.expenseCategories,
    incomeCategories:    Array.isArray(raw.incomeCategories)     ? raw.incomeCategories   : DEFAULT.incomeCategories,
    transactions:        Array.isArray(raw.transactions)         ? raw.transactions        : [],
    holdings:            Array.isArray(raw.holdings)             ? raw.holdings            : [],
    investmentTx:        Array.isArray(raw.investmentTx)         ? raw.investmentTx        : [],
    fxRates:           (raw.fxRates && typeof raw.fxRates === "object") ? raw.fxRates    : DEFAULT.fxRates,
    fixedDeposits:       Array.isArray(raw.fixedDeposits)        ? raw.fixedDeposits       : [],
    marketPrices:       (raw.marketPrices && typeof raw.marketPrices === "object") ? raw.marketPrices : {},
    corporateActions:        Array.isArray(raw.corporateActions)         ? raw.corporateActions        : [],
    corporateActionsMaster:  Array.isArray(raw.corporateActionsMaster)  ? raw.corporateActionsMaster : [],
    tradeBalanceEffects: Array.isArray(raw.tradeBalanceEffects)  ? raw.tradeBalanceEffects : [],
    stocks:              Array.isArray(raw.stocks)               ? raw.stocks              : [],
  };
}

// ─── STORAGE: CLOUD-ONLY ─────────────────────────────────────────────────────
//
// Architecture (v20+):
//   • Supabase is the ONLY source of truth — no localStorage for data at all.
//   • App starts with empty state and shows a loading screen.
//   • On login: pull cloud → dispatch SET → that is the entire state.
//   • On every state change: push to Supabase only.
//   • localStorage is NOT used for data (prevents stale/doubled cache issues).
//
// ─────────────────────────────────────────────────────────────────────────────

// saveLocal: intentional no-op — localStorage disabled to prevent stale data bugs.
// Kept as a named function so any internal call sites compile without error.
function saveLocal(_s) { /* cloud-only: localStorage writes disabled */ }

// loadLocal: returns empty state — app always waits for cloud on login.
function loadLocal() { return sanitize({}); }

// ─── DEDUP INVESTMENT TRANSACTIONS ───────────────────────────────────────────
// Removes trades that were duplicated by earlier migration/import bugs.
//
// TWO-TIER DEDUP STRATEGY:
//
// Tier 1 — externalTradeId (Zerodha trade_id, broker ID, etc.)
//   If a trade has an externalTradeId, that is the authoritative unique key.
//   Two trades with the same externalTradeId are always duplicates regardless
//   of any other field.
//
// Tier 2 — content fingerprint (fallback for manually-entered trades only)
//   Only applied to trades that have NO externalTradeId.
//   Key: symbol + date + type + quantity + price + accountId
//   This is intentionally narrow — only exact matches on ALL six fields
//   are considered duplicates. A legitimate same-day same-price second buy
//   of the same stock in the same account is not caught here (correct behaviour:
//   those are genuinely two separate trades that happen to share fields).
//   The migration bug produced EXACT copies of every record, so this still
//   catches all migration-doubled manual trades.
//
// After dedup, holdings and tradeBalanceEffects are rebuilt from scratch.
function deduplicateState(s) {
  const txs = s.investmentTx || [];
  if (txs.length === 0) return s;

  const seenExtIds = new Set(); // Tier 1: externalTradeId → seen?
  const seenFP     = new Set(); // Tier 2: content fingerprint → seen?
  const unique     = [];
  let   removed    = 0;

  for (const tx of txs) {
    const extId = tx.externalTradeId ? String(tx.externalTradeId).trim() : "";

    if (extId) {
      // ── Tier 1: broker trade ID is the sole dedup key ──────────────────────
      if (seenExtIds.has(extId)) {
        removed++;
        console.log(`[Dedup] Drop duplicate externalTradeId=${extId} (${tx.symbol} ${tx.type} ${tx.date})`);
        continue;
      }
      seenExtIds.add(extId);
    } else {
      // ── Tier 2: no broker ID — use exact content fingerprint ───────────────
      // Only catches trades that are IDENTICAL on all six fields.
      const fp = [
        (tx.symbol   || "").toUpperCase(),
        tx.date      || "",
        tx.type      || "",
        String(parseFloat(tx.quantity) || 0),
        String(parseFloat(tx.price)    || 0),
        tx.accountId || "",
      ].join("|");

      if (seenFP.has(fp)) {
        removed++;
        console.log(`[Dedup] Drop duplicate fingerprint ${tx.symbol} ${tx.type} ${tx.quantity}@${tx.price} on ${tx.date}`);
        continue;
      }
      seenFP.add(fp);
    }

    unique.push(tx);
  }

  if (removed === 0) return s; // nothing changed

  console.log(`[Dedup] Removed ${removed} duplicate trade(s). ${unique.length} unique trades remain.`);

  // Rebuild holdings and balance effects from the clean tx list
  const sorted = [...unique].sort((a, b) => new Date(a.date) - new Date(b.date));
  const { holdings } = rebuildHoldings(sorted, []);
  const fdEffects    = (s.tradeBalanceEffects || []).filter(e => e.isFD);
  const stockEffects = buildTradeBalanceEffects(sorted, [], s.fxRates || DEFAULT?.fxRates || {});

  return {
    ...s,
    investmentTx:        sorted,
    holdings,
    tradeBalanceEffects: [...stockEffects, ...fdEffects],
  };
}

// ─── INVESTMENT DATA MIGRATION LAYER ─────────────────────────────────────────
//
// Problem: Each version bump changes the STORAGE_KEY (wealthmap_v1 → v16).
// When the app loads with a new key, the old key's data is ignored, making
// holdings/trades appear to vanish.
//
// Solution: On every cold start, scan all known prior keys, find the most
// recent one that has investment data, migrate its records into the current
// state format, rebuild holdings + balance effects, and merge additively into
// the current key. Migration only runs when current state has zero trades —
// this is the reliable guard against double-counting.
//
// Field mapping (old → new):
//   investments / portfolio / investmentTransactions / trades → investmentTx
//   Each record: symbol/stock → symbol, qty/quantity → quantity,
//                price/rate → price, date/tradeDate/trade_date → date,
//                type/tradeType/trade_type → type (buy|sell)
// ─────────────────────────────────────────────────────────────────────────────

// All storage keys ever used by WealthMap (oldest first)
const ALL_LEGACY_KEYS = [
  "wealthmap",
  "wealthmap-v1",
  "wealthmap_v1",  "wealthmap_v2",  "wealthmap_v3",  "wealthmap_v4",
  "wealthmap_v5",  "wealthmap_v6",  "wealthmap_v7",  "wealthmap_v8",
  "wealthmap_v9",  "wealthmap_v10", "wealthmap_v11", "wealthmap_v12",
  "wealthmap_v13", "wealthmap_v14", "wealthmap_v15", "wealthmap_v16",
  "wealthmap_v17", "wealthmap_v18", "wealthmap_v19", "wealthmap_v20",
  "wealthmap_v21", "wealthmap_v22", "wealthmap_v23", "wealthmap_v24",
  "wealthmap_v25", "wealthmap_v26", "wealthmap_v27", "wealthmap_v28",
  "wealthmap_v29", "wealthmap_v30", "wealthmap_v31", "wealthmap_v32",
  "wealthmap_v33", "wealthmap_v34", "wealthmap_v35", "wealthmap_v36",
  "wealthmap_v37", "wealthmap_v38", "wealthmap_v39", "wealthmap_v40",
  "wealthmap_v41", "wealthmap_v42", "wealthmap_v43", "wealthmap_v44",
  "wealthmap_v45", "wealthmap_v46", "wealthmap_v47",
  // Current key (wealthmap_v48) is excluded — handled by loadLocal directly
];

// Normalise one raw trade/investment record from any old schema → current itx shape
function migrateOneTrade(raw, fallbackAccountId) {
  if (!raw || typeof raw !== "object") return null;

  // Symbol — various old names
  const symbol = (
    raw.symbol || raw.stock || raw.stock_name || raw.ticker || raw.scrip || ""
  ).toString().toUpperCase().trim();
  if (!symbol) return null;

  // Quantity
  const quantity = parseFloat(
    raw.quantity ?? raw.qty ?? raw.units ?? raw.shares ?? 0
  );
  if (isNaN(quantity) || quantity <= 0) return null;

  // Price
  const price = parseFloat(
    raw.price ?? raw.rate ?? raw.nav ?? raw.buyPrice ?? raw.tradePrice ?? 0
  );
  if (isNaN(price) || price < 0) return null;

  // Date — accept ISO strings, YYYY-MM-DD, or Date objects
  let date = (
    raw.date || raw.tradeDate || raw.trade_date ||
    raw.investedDate || raw.purchaseDate || raw.created_at || ""
  ).toString().trim();
  // Try to normalise to YYYY-MM-DD
  if (date && !/^\d{4}-\d{2}-\d{2}/.test(date)) {
    const d = new Date(date);
    if (!isNaN(d)) date = d.toISOString().slice(0, 10);
  }
  if (!date) date = new Date().toISOString().slice(0, 10);

  // Trade type — default to "buy" if ambiguous
  const rawType = (
    raw.type || raw.tradeType || raw.trade_type || raw.txType || "buy"
  ).toString().toLowerCase().trim();
  const type = rawType === "sell" ? "sell" : "buy";

  // Accounts
  const accountId       = raw.accountId       || raw.investmentAccountId || fallbackAccountId || "";
  const sourceAccountId = raw.sourceAccountId || raw.bankAccountId       || "";

  // External trade ID (preserve for dedup)
  const externalTradeId = raw.externalTradeId || raw.trade_id || raw.tradeId || raw.id || "";

  const id = raw.id && typeof raw.id === "string" && raw.id.startsWith("tx_")
    ? raw.id           // keep existing well-formed IDs
    : "migrated_" + (externalTradeId || (symbol + "_" + date + "_" + Math.random().toString(36).slice(2, 7)));

  return {
    id,
    holdingId:       raw.holdingId || "h_" + symbol + "_" + accountId,
    type,
    invType:         raw.invType || raw.investmentType || (raw.assetType === "mf" ? "mf" : "stock"),
    symbol,
    name:            raw.name || raw.companyName || raw.stockName || symbol,
    quantity,
    price,
    currency:        raw.currency || "INR",
    date,
    accountId,
    sourceAccountId,
    brokerage:       parseFloat(raw.brokerage || raw.commission || 0) || 0,
    note:            raw.note || raw.notes || raw.remarks || "",
    externalTradeId,
    _migrated:       true,
  };
}

// Extract investment transactions from a raw stored object using all known field names
function extractLegacyTrades(raw, fallbackAccountId) {
  const candidates = [];

  // Try every known array field name that could hold trades
  const fields = [
    "investmentTx",           // current name (v8+)
    "investmentTransactions", // older alias
    "trades",                 // some versions used this
    "investments",            // early versions
    "portfolio",              // some experimental versions
    "stockTrades",
    "mutualFundTrades",
    "txHistory",
  ];

  fields.forEach(f => {
    if (Array.isArray(raw[f])) {
      raw[f].forEach(r => {
        const t = migrateOneTrade(r, fallbackAccountId);
        if (t) candidates.push(t);
      });
    }
  });

  return candidates;
}

// Main migration function — called once at startup inside loadLocal.
// Returns the merged, migrated state to use as the initial app state.
function migrateFromOlderVersion(currentState) {
  // ── GUARD: Never migrate when current state already has investment data ─────
  // Migration is ONLY for bootstrapping a fresh/empty key from an old one.
  // If the user already has trades in the current state (whether from a previous
  // migration, manual entry, or import), we must NOT add legacy trades again —
  // that would double-count everything.
  //
  // The old stamp-based approach (writing __migrated_to on the source key) was
  // unreliable because the cloud sync overwrites localStorage, erasing the stamp.
  // This guard is the only reliable protection.
  const currentTxCount = (currentState.investmentTx || []).length;
  if (currentTxCount > 0) {
    console.log("[Migration] Current state has", currentTxCount, "trade(s) — skipping migration.");
    return currentState;
  }

  let migratedTxs   = [];
  let sourceKeyUsed = null;

  // Scan from newest legacy key to oldest — take the first one with trades
  const keysToScan = [...ALL_LEGACY_KEYS].reverse();

  for (const key of keysToScan) {
    if (key === STORAGE_KEY) continue;

    let raw = null;
    try {
      const stored = localStorage.getItem(key);
      if (!stored) continue;
      raw = JSON.parse(stored);
    } catch (e) {
      console.warn("[Migration] Could not parse key:", key, e);
      continue;
    }

    // Determine the fallback investment account from old state
    const oldAccounts = Array.isArray(raw?.accounts) ? raw.accounts : [];
    const oldCats     = Array.isArray(raw?.accountCategories) ? raw.accountCategories : DEFAULT.accountCategories;
    const invCat      = oldCats.find(c => c.isInvestmentType);
    const invAcc      = invCat
      ? oldAccounts.find(a => a.categoryId === invCat.id || a.account_type === invCat.id)
      : null;
    const fallbackAccId = invAcc?.id || oldAccounts[0]?.id || "";

    const trades = extractLegacyTrades(raw, fallbackAccId);

    if (trades.length === 0) {
      console.log("[Migration] No trades found in key:", key, "(skipping)");
      continue;
    }

    console.log("[Migration] Found", trades.length, "trade record(s) in key:", key);
    migratedTxs   = trades;
    sourceKeyUsed = key;
    break;
  }

  // ── Full-state migration: for recent same-schema versions (v16+) ────────
  // Scan again for the most recent key that has the most complete state
  // (accounts, transactions, etc.) — not just investment trades.
  let bestKey   = null;
  let bestRaw   = null;
  let bestScore = 0;

  for (const key of [...ALL_LEGACY_KEYS].reverse()) {
    if (key === STORAGE_KEY) continue;
    try {
      const stored = localStorage.getItem(key);
      if (!stored) continue;
      const raw = JSON.parse(stored);
      // Score by total data richness
      const score =
        (Array.isArray(raw.accounts)      ? raw.accounts.length      : 0) * 10 +
        (Array.isArray(raw.transactions)  ? raw.transactions.length  : 0) * 5  +
        (Array.isArray(raw.investmentTx)  ? raw.investmentTx.length  : 0) * 8  +
        (Array.isArray(raw.fixedDeposits) ? raw.fixedDeposits.length : 0) * 6;
      if (score > bestScore) {
        bestScore = score;
        bestKey   = key;
        bestRaw   = raw;
      }
    } catch { continue; }
  }

  if (!bestRaw) {
    console.log("[Migration] No legacy data found — nothing to migrate.");
    return currentState;
  }

  console.log("[Migration] ✅ Full state migration from", bestKey, "(score:", bestScore, ")");

  // Carry over all known state fields from the best legacy key
  const fullMigrated = {
    ...currentState,          // keep defaults for any new fields
    ...bestRaw,               // overlay all legacy state
    // Ensure these critical fields are always arrays
    accounts:            Array.isArray(bestRaw.accounts)            ? bestRaw.accounts            : currentState.accounts            || [],
    transactions:        Array.isArray(bestRaw.transactions)        ? bestRaw.transactions        : currentState.transactions        || [],
    investmentTx:        Array.isArray(bestRaw.investmentTx)        ? bestRaw.investmentTx        : [],
    fixedDeposits:       Array.isArray(bestRaw.fixedDeposits)       ? bestRaw.fixedDeposits       : [],
    holdings:            Array.isArray(bestRaw.holdings)            ? bestRaw.holdings            : [],
    corporateActions:    Array.isArray(bestRaw.corporateActions)    ? bestRaw.corporateActions    : [],
    corporateActionsMaster: Array.isArray(bestRaw.corporateActionsMaster) ? bestRaw.corporateActionsMaster : [],
    stocks:              Array.isArray(bestRaw.stocks)              ? bestRaw.stocks              : [],
    expenses:            Array.isArray(bestRaw.expenses)            ? bestRaw.expenses            : [],
    tradeBalanceEffects: Array.isArray(bestRaw.tradeBalanceEffects) ? bestRaw.tradeBalanceEffects : [],
    accountCategories:   Array.isArray(bestRaw.accountCategories)   ? bestRaw.accountCategories   : currentState.accountCategories   || [],
  };

  console.log("[Migration] Migrated:",
    fullMigrated.accounts.length, "accounts,",
    fullMigrated.transactions.length, "transactions,",
    fullMigrated.investmentTx.length, "investment trades,",
    fullMigrated.fixedDeposits.length, "FDs"
  );

  return fullMigrated;
}

// ─── FULLY NORMALIZED DB LAYER ───────────────────────────────────────────────
//
// All 13 tables use real typed columns. Zero JSON blobs for user data.
// Only two jsonb fields remain (both justified):
//   wm_corporate_actions.result_stocks — variable-length array of sub-objects
//   wm_holdings.lots                   — ordered FIFO lot array [{qty,price,date,txId}]
//
// Table → App object mappers (rowTo*) and reverse (appTo*Row)
// ─────────────────────────────────────────────────────────────────────────────

// ── DB row → App object ───────────────────────────────────────────────────────

function rowToAccount(r) {
  // Support both old __cc__ note format (pre-migration) and new proper columns
  const { ccFields, realNote } = r.note?.startsWith("__cc__") ? decodeCCNote(r) : { ccFields: {}, realNote: r.note||"" };
  const isCreditCard = r.is_credit_card || ccFields.isCreditCard || false;
  return {
    id:                  r.id,
    name:                r.name || "",
    account_type:        r.account_type || "other",
    categoryId:          r.account_type || "other",
    balance:             parseFloat(r.balance) || 0,
    currency:            r.currency || "INR",
    is_active:           r.is_active !== false,
    disabled:            r.is_active === false,
    include_in_networth: r.include_in_networth !== false,
    includeInNetWorth:   r.include_in_networth !== false,
    color:               r.color || "#F5C518",
    icon:                r.icon || "🏦",
    note:                realNote,
    openingBalance:      parseFloat(r.opening_balance) || 0,
    credit_limit:        r.credit_limit != null ? parseFloat(r.credit_limit) : undefined,
    due_date:            r.due_date     != null ? parseInt(r.due_date)       : undefined,
    // CC settings from proper columns (fallback to decoded __cc__ note for pre-migration data)
    isCreditCard:        isCreditCard,
    billDay:             r.bill_day   ?? ccFields.billDay   ?? undefined,
    dueDay:              r.due_day    ?? ccFields.dueDay    ?? undefined,
    cbTiming:            r.cb_timing  || ccFields.cbTiming  || undefined,
    cbType:              r.cb_type    || ccFields.cbType    || undefined,
    cbTiers:             r.cb_tiers   || ccFields.cbTiers   || undefined,  // loaded separately via wm_cc_tiers
    cbCreditSelf:        r.cb_credit_self ?? ccFields.cbCreditSelf ?? true,
    cbWalletId:          r.cb_wallet_id || ccFields.cbWalletId || undefined,
  };
}

function rowToTx(r) {
  return {
    id:             r.id,
    type:           r.type,
    amount:         parseFloat(r.amount) || 0,
    currency:       r.currency || "INR",
    date:           r.date ? String(r.date).slice(0,10) : "",
    categoryId:     r.category_id || "",
    subCategoryId:  r.sub_category_id || null,
    accountId:      r.account_id  || "",
    fromAccountId:  r.from_account_id || "",
    toAccountId:    r.to_account_id   || "",
    toAmount:       r.to_amount   != null ? parseFloat(r.to_amount)   : null,
    toCurrency:     r.to_currency || null,
    ...(() => {
      // Support both new proper columns and old __tx__/__cb__ note encoding (pre-migration)
      let note = r.note || "";
      let expectedCashbackPct = r.expected_cashback_pct ?? undefined;
      let expectedCashbackAmt = r.expected_cashback_amt ?? undefined;
      let cbCardId            = r.cb_card_id            || undefined;
      let cbCreditSelf        = r.cb_credit_self        ?? true;
      let cbCreditAccId       = r.cb_credit_acc_id      || undefined;
      // Fallback: decode old note encoding if proper columns missing
      if (note.startsWith("__tx__") || note.startsWith("__cb__")) {
        const tx = decodeTxNote(note);
        const cb = decodeCBNote(tx.realNote);
        expectedCashbackPct = expectedCashbackPct ?? tx.expectedCashbackPct;
        expectedCashbackAmt = expectedCashbackAmt ?? tx.expectedCashbackAmt;
        cbCardId            = cbCardId            ?? cb.cbCardId;
        note                = cb.realNote;
      }
      return { note, expectedCashbackPct, expectedCashbackAmt, cbCardId, cbCreditSelf, cbCreditAccId };
    })(),
    txTime:         r.tx_time || "",
    refundedAmount: parseFloat(r.refunded_amount) || 0,
    isRefunded:     r.is_refunded || false,
  };
}

