// ── App object → DB row ───────────────────────────────────────────────────────

function encodeCCNote(a) {
  // Pack CC-specific fields into the note field as a JSON prefix.
  // Format: "__cc__<json>|<realNote>"  — the "|" separator is only added if there is a real note.
  const realNote = (a.note || "").replace(/^__cc__[^|]*\|?/, ""); // strip any old cc prefix
  if (!a.isCreditCard && !(a.account_type||a.categoryId||"").includes("cat_cc")) return realNote;
  const cc = {
    isCreditCard: true,
    billDay:      a.billDay      != null ? parseInt(a.billDay)  : undefined,
    dueDay:       a.dueDay       != null ? parseInt(a.dueDay)   : undefined,
    cbTiming:     a.cbTiming     || undefined,
    cbType:       a.cbType       || undefined,
    cbTiers:      a.cbTiers      || undefined,
    cbCreditSelf: a.cbCreditSelf !== undefined ? a.cbCreditSelf : undefined,
    cbWalletId:   a.cbWalletId   || undefined,
  };
  // Only include defined keys
  const ccClean = Object.fromEntries(Object.entries(cc).filter(([,v])=>v!==undefined));
  const prefix = "__cc__" + JSON.stringify(ccClean);
  return realNote ? prefix + "|" + realNote : prefix;
}

function decodeCCNote(row) {
  // Extract CC fields from packed note field. Returns { ccFields, realNote }.
  const note = row.note || "";
  if (!note.startsWith("__cc__")) return { ccFields: {}, realNote: note };
  const pipeIdx = note.indexOf("|");
  const jsonStr = pipeIdx === -1 ? note.slice(6) : note.slice(6, pipeIdx);
  const realNote = pipeIdx === -1 ? "" : note.slice(pipeIdx + 1);
  try {
    return { ccFields: JSON.parse(jsonStr), realNote };
  } catch { return { ccFields: {}, realNote: note }; }
}

// ─── Cashback income tx helpers ──────────────────────────────────────────────
// Cashback received income txs store card link in note: "__cb__<cardId>|<realNote>"
function encodeCBNote(t) {
  const realNote = (t.note || "").replace(/^__cb__\{[^}]*\}\|?/, "").replace(/^__cb__[^|]*\|?/, "");
  if (!t.cbCardId) return realNote;
  const cbData = { id: t.cbCardId };
  if (t.cbCreditSelf === false) cbData.self = false;
  if (t.cbCreditAccId) cbData.acc = t.cbCreditAccId;
  const prefix = "__cb__" + JSON.stringify(cbData);
  return realNote ? prefix + "|" + realNote : prefix;
}
function decodeCBNote(note) {
  if (!(note||"").startsWith("__cb__")) return { cbCardId: null, cbCreditSelf: true, cbCreditAccId: "", realNote: note||"" };
  const pipeIdx = note.indexOf("|");
  const raw     = pipeIdx === -1 ? note.slice(6) : note.slice(6, pipeIdx);
  const realNote = pipeIdx === -1 ? "" : note.slice(pipeIdx + 1);
  // Support both old format "__cb__<cardId>" and new format "__cb__{"id":"...","self":false}"
  if (raw.startsWith("{")) {
    try {
      const d = JSON.parse(raw);
      return { cbCardId: d.id||null, cbCreditSelf: d.self !== false, cbCreditAccId: d.acc||"", realNote };
    } catch { return { cbCardId: null, cbCreditSelf: true, cbCreditAccId: "", realNote: note }; }
  }
  // Legacy: plain card id
  return { cbCardId: raw || null, cbCreditSelf: true, cbCreditAccId: "", realNote };
}

// ─── Tx cashback note helpers ─────────────────────────────────────────────────
// expectedCashbackPct and expectedCashbackAmt packed into note:
// "__tx__{"cb":1,"cba":12.50}|real note"
function encodeTxNote(t) {
  const realNote = (t.note || "").replace(/^__tx__\{[^}]*\}\|?/, "");
  const cbPct = parseFloat(t.expectedCashbackPct)||0;
  const cbAmt = parseFloat(t.expectedCashbackAmt)||0;
  if (!cbPct) return realNote;
  const prefix = "__tx__" + JSON.stringify({ cb: cbPct, cba: cbAmt });
  return realNote ? prefix + "|" + realNote : prefix;
}
function decodeTxNote(note) {
  if (!(note||"").startsWith("__tx__")) return { expectedCashbackPct: undefined, expectedCashbackAmt: undefined, realNote: note||"" };
  const pipeIdx = note.indexOf("|");
  const raw     = pipeIdx === -1 ? note.slice(6) : note.slice(6, pipeIdx);
  const realNote = pipeIdx === -1 ? "" : note.slice(pipeIdx + 1);
  try {
    const d = JSON.parse(raw);
    return { expectedCashbackPct: d.cb||undefined, expectedCashbackAmt: d.cba||undefined, realNote };
  } catch { return { expectedCashbackPct: undefined, expectedCashbackAmt: undefined, realNote: note }; }
}

function accountToRow(a, uid) {
  return {
    id: a.id, user_id: uid,
    name:                a.name || "",
    account_type:        a.account_type || a.categoryId || "other",
    balance:             parseFloat(a.balance) || 0,
    currency:            a.currency || "INR",
    is_active:           a.is_active !== false && a.disabled !== true,
    include_in_networth: a.include_in_networth !== false && a.includeInNetWorth !== false,
    color:               a.color || "#F5C518",
    icon:                a.icon  || "🏦",
    note:                a.note  || "",
    opening_balance:     parseFloat(a.openingBalance) || 0,
    credit_limit:        a.credit_limit != null ? parseFloat(a.credit_limit) : null,
    due_date:            a.due_date     != null ? parseInt(a.due_date)       : null,
    // CC settings — proper columns (no JSON encoding)
    is_credit_card:      a.isCreditCard || false,
    bill_day:            a.billDay  != null ? parseInt(a.billDay)  : null,
    due_day:             a.dueDay   != null ? parseInt(a.dueDay)   : null,
    cb_timing:           a.cbTiming || null,
    cb_type:             a.cbType   || null,
    cb_credit_self:      a.cbCreditSelf !== undefined ? a.cbCreditSelf : true,
    cb_wallet_id:        a.cbWalletId || null,
  };
}

