// Flatten all holdings' lots into a single array for pushCloud
function holdingsToLotRows(holdings, uid) {
  const rows = [];
  for (const h of holdings || []) {
    for (const lot of h.lots || []) {
      // Stable lot ID: holdingId + txId
      const lotId = "lot_" + h.id + "_" + (lot.txId || lot.date || rows.length);
      rows.push(holdingLotToRow({ ...lot, id: lotId, holdingId: h.id }, uid));
    }
  }
  return rows;
}

