// ── Generic DB helpers ────────────────────────────────────────────────────────

async function dbFetch(table, userId, mapFn) {
  try {
    const { data, error } = await supabase.from(table).select("*").eq("user_id", userId);
    if (error) { console.warn(`[DB] fetch ${table}:`, error.message); return []; }
    return (data || []).map(mapFn);
  } catch(e) { console.warn(`[DB] fetch ${table}:`, e); return []; }
}

async function dbUpsert(table, rows) {
  if (!rows || rows.length === 0) return;
  const { error } = await supabase.from(table).upsert(rows, { onConflict: "id,user_id" });
  if (error) console.error(`[DB] upsert ${table}:`, error.message);
}

async function dbDelete(table, userId, ids) {
  if (!ids || ids.length === 0) return;
  const { error } = await supabase.from(table).delete().eq("user_id", userId).in("id", ids);
  if (error) console.error(`[DB] delete ${table}:`, error.message);
}

// Delete all lots for specific holding_ids — used when a holding is removed/changed
async function dbDeleteLotsByHoldingIds(userId, holdingIds) {
  if (!holdingIds || holdingIds.length === 0) return;
  const { error } = await supabase
    .from("wm_holding_lots")
    .delete()
    .eq("user_id", userId)
    .in("holding_id", holdingIds);
  if (error) console.error("[DB] delete wm_holding_lots by holding_id:", error.message);
}

// ── pullCloud: fetch all 13 tables in parallel ────────────────────────────────
async function pullCloud(userId) {
  if (!userId) return null;
  try {
    const [
      accounts, accountCategories, expenseCategories, incomeCategories,
      subCategories,
      transactions, investmentTx, fixedDeposits, stocks, corporateActions,
      caMaster, holdingsRaw, holdingLots, balanceEffects,
      mpRows, fxRows, ccTiersRaw, caResultStocksRaw,
    ] = await Promise.all([
      dbFetch("wm_accounts",              userId, rowToAccount),
      dbFetch("wm_account_categories",    userId, rowToAccountCategory),
      dbFetch("wm_expense_categories",    userId, rowToExpenseCategory),
      dbFetch("wm_income_categories",     userId, rowToIncomeCategory),
      dbFetch("wm_sub_categories",        userId, rowToSubCategory),
      dbFetch("wm_transactions",          userId, rowToTx),
      dbFetch("wm_investment_tx",         userId, rowToInvestmentTx),
      dbFetch("wm_fixed_deposits",        userId, rowToFD),
      dbFetch("wm_stocks",                userId, rowToStock),
      dbFetch("wm_corporate_actions",     userId, rowToCorporateAction),
      dbFetch("wm_ca_master",             userId, rowToCaMaster),
      dbFetch("wm_holdings",              userId, r => rowToHolding(r, null)),
      dbFetch("wm_holding_lots",          userId, rowToHoldingLot),
      dbFetch("wm_trade_balance_effects", userId, rowToBalanceEffect),
      supabase.from("wm_market_prices").select("symbol,current_price,last_updated").eq("user_id", userId),
      supabase.from("wm_fx_rates").select("currency,rate").eq("user_id", userId),
      dbFetch("wm_cc_tiers",              userId, r => r).catch(() => []),
      dbFetch("wm_ca_result_stocks",      userId, r => r).catch(() => []),
    ]);

    // Join sub-categories into their parent expense/income categories
    const subsByParent = new Map();
    for (const s of subCategories) {
      if (!subsByParent.has(s.parentId)) subsByParent.set(s.parentId, []);
      subsByParent.get(s.parentId).push(s);
    }
    expenseCategories.forEach(c => { c.subCategories = subsByParent.get(c.id) || []; });
    incomeCategories.forEach(c  => { c.subCategories = subsByParent.get(c.id) || []; });

    // Assemble marketPrices { symbol: {current_price, last_updated} }
    const marketPrices = {};
    (mpRows.data || []).forEach(r => {
      marketPrices[r.symbol] = { current_price: parseFloat(r.current_price)||0, last_updated: r.last_updated };
    });

    // Assemble fxRates { currency: rate }
    const fxRates = { ...DEFAULT.fxRates };
    (fxRows.data || []).forEach(r => { fxRates[r.currency] = parseFloat(r.rate) || 1; });

    // Join holdingLots → holdings: build Map<holdingId, lot[]>
    const lotsMap = new Map();
    for (const lot of holdingLots) {
      if (!lotsMap.has(lot.holdingId)) lotsMap.set(lot.holdingId, []);
      lotsMap.get(lot.holdingId).push({ qty: lot.qty, price: lot.price, date: lot.date, txId: lot.txId });
    }
    // Re-map holdings with their lots attached
    const holdings = holdingsRaw.map(h => ({ ...h, lots: lotsMap.get(h.id) || [] }));

    const hasData = accounts.length > 0 || investmentTx.length > 0 ||
                    transactions.length > 0 || fixedDeposits.length > 0;

    if (!hasData) {
      const migrated = await migrateFromLegacyBlob(userId);
      if (migrated) return migrated;
      console.log("[DB] No data — fresh start.");
      return null;
    }

    // Join CC tiers to accounts: attach cbTiers array to each account
    const ccTiersByAcc = {};
    (ccTiersRaw || []).forEach(t => {
      if (!ccTiersByAcc[t.account_id]) ccTiersByAcc[t.account_id] = [];
      ccTiersByAcc[t.account_id].push({ pct: parseFloat(t.pct)||0, limit: t.cap_amount ? parseFloat(t.cap_amount) : null });
    });
    const accountsWithTiers = accounts.map(a => ({
      ...a,
      cbTiers: ccTiersByAcc[a.id] || a.cbTiers || [],
    }));

    // Join CA result stocks to corporate actions
    const caRsByCA = {};
    (caResultStocksRaw || []).forEach(r => {
      if (!caRsByCA[r.ca_id]) caRsByCA[r.ca_id] = [];
      caRsByCA[r.ca_id].push({
        symbol: r.symbol, name: r.name, cost_pct: parseFloat(r.cost_pct)||0,
        ratio_from: parseFloat(r.ratio_from)||1, ratio_to: parseFloat(r.ratio_to)||1,
        accountId: r.account_id,
      });
    });
    const corporateActionsWithRS = corporateActions.map(ca => ({
      ...ca,
      result_stocks: caRsByCA[ca.id] || ca.result_stocks || [],
    }));

    // Deduplicate holdings: if DB has multiple rows for same symbol+accountId, keep the
    // one with the highest quantity (most data). This handles stale duplicate rows from
    // pre-v79 era where merged/demerged stocks could create ghost holding entries.
    const holdingsDeduped = (() => {
      const seen = new Map(); // key: symbol_accountId → best holding
      for (const h of holdings) {
        const key = (h.symbol||"") + "_" + (h.accountId||"");
        const prev = seen.get(key);
        if (!prev || (parseFloat(h.invested_amount)||0) > (parseFloat(prev.invested_amount)||0)) {
          seen.set(key, h);
        }
      }
      return [...seen.values()];
    })();
    if (holdingsDeduped.length < holdings.length) {
      console.log(`[DB] Deduplicated holdings: removed ${holdings.length - holdingsDeduped.length} duplicate(s)`);
    }

    const assembled = {
      accounts: accountsWithTiers,
      accountCategories:   accountCategories.length > 0 ? accountCategories : DEFAULT.accountCategories,
      expenseCategories:   expenseCategories.length > 0 ? expenseCategories : DEFAULT.expenseCategories,
      incomeCategories:    incomeCategories.length  > 0 ? incomeCategories  : DEFAULT.incomeCategories,
      transactions,
      investmentTx,
      fixedDeposits,
      stocks,
      corporateActions: corporateActionsWithRS,
      corporateActionsMaster: caMaster,
      holdings: holdingsDeduped,
      tradeBalanceEffects: balanceEffects,
      marketPrices,
      fxRates,
    };

    console.log("[DB] Loaded:", investmentTx.length, "trades,", accounts.length,
      "accounts,", corporateActions.length, "corporate actions,", holdings.length, "holdings");
    // ── Reconstruct missing FD close effects ─────────────────────────────────
    // If an FD is closed (status=closed) but its close credit effect is missing
    // from tradeBalanceEffects, recreate it so account balances are correct.
    const existingEffIds = new Set((assembled.tradeBalanceEffects||[]).map(e=>e.id));
    const repairedEffects = [...(assembled.tradeBalanceEffects||[])];
    let repaired = 0;
    for (const fd of (assembled.fixedDeposits||[])) {
      if (fd.status !== "closed" || !fd.closedAccId || !fd.amount) continue;
      const closeEffId = "fdclose_" + fd.id;
      if (!existingEffIds.has(closeEffId)) {
        // Recreate the close credit effect
        repairedEffects.push({
          id:        closeEffId,
          accountId: fd.closedAccId,
          amount:    parseFloat(fd.amount),
          sign:      +1,
          tradeId:   fd.id + "_close",
          date:      fd.closeDate || null,
          isFD:      true,
        });
        // Also remove original deduction effect (fdeff_*) — money was returned
        const effIdx = repairedEffects.findIndex(e => e.id === "fdeff_" + fd.id);
        if (effIdx >= 0) repairedEffects.splice(effIdx, 1);
        repaired++;
      }
    }
    if (repaired > 0) {
      console.log(`[DB] Reconstructed ${repaired} missing FD close effect(s)`);
      assembled.tradeBalanceEffects = repairedEffects;
    }

    return deduplicateState(sanitize(assembled));

  } catch(e) {
    console.error("[DB] pullCloud exception:", e);
    return null;
  }
}

// ── pushCloud: diff and write only changed rows ───────────────────────────────
let _lastPushedState = null;

async function pushCloud(userId, s) {
  if (!userId || !s) return;
  const prev = _lastPushedState;

  function diff(newArr, prevArr, toRowFn) {
    const n = newArr  || [];
    const p = prevArr || [];
    const prevMap = new Map(p.map(r => [r.id, JSON.stringify(r)]));
    const newMap  = new Map(n.map(r => [r.id, r]));
    return {
      toUpsert: n.filter(r => prevMap.get(r.id) !== JSON.stringify(r)).map(r => toRowFn(r, userId)),
      toDelete: p.filter(r => !newMap.has(r.id)).map(r => r.id),
    };
  }

  // Build wm_cc_tiers rows from accounts for diffing
  const ccTierRows = [];
  (s.accounts || []).forEach(a => {
    (a.cbTiers || []).forEach((tier, idx) => {
      ccTierRows.push({
        id: a.id + "_tier_" + idx, user_id: userId,
        account_id: a.id, sort_order: idx,
        pct: parseFloat(tier.pct)||0,
        cap_amount: tier.limit != null ? parseFloat(tier.limit) : null,
      });
    });
  });
  const prevCCTierRows = [];
  (prev?.accounts || []).forEach(a => {
    (a.cbTiers || []).forEach((tier, idx) => {
      prevCCTierRows.push({ id: a.id + "_tier_" + idx });
    });
  });

  const collections = [
    ["wm_accounts",              s.accounts,          prev?.accounts,          accountToRow],
    ["wm_account_categories",    s.accountCategories, prev?.accountCategories, accountCategoryToRow],
    ["wm_expense_categories",    s.expenseCategories, prev?.expenseCategories, expenseCategoryToRow],
    ["wm_income_categories",     s.incomeCategories,  prev?.incomeCategories,  incomeCategoryToRow],
    ["wm_transactions",          s.transactions,      prev?.transactions,      txToRow],
    ["wm_investment_tx",         s.investmentTx,      prev?.investmentTx,      investmentTxToRow],
    ["wm_fixed_deposits",        s.fixedDeposits,     prev?.fixedDeposits,     fdToRow],
    ["wm_stocks",                s.stocks,            prev?.stocks,            stockToRow],
    ["wm_corporate_actions",     s.corporateActions,         prev?.corporateActions,         corporateActionToRow],
    ["wm_ca_master",             s.corporateActionsMaster,  prev?.corporateActionsMaster,  caMasterToRow],
    // wm_cc_tiers synced below via delete+reinsert
    ["wm_holdings",              s.holdings,          prev?.holdings,          holdingToRow],
    // NOTE: wm_holding_lots is synced separately below via delete-and-reinsert strategy
    ["wm_trade_balance_effects", s.tradeBalanceEffects, prev?.tradeBalanceEffects, balanceEffectToRow],
  ];

  const ops = [];
  for (const [table, newArr, prevArr, toRowFn] of collections) {
    const { toUpsert, toDelete } = diff(newArr, prevArr, toRowFn);
    if (toUpsert.length > 0) { ops.push(dbUpsert(table, toUpsert)); }
    if (toDelete.length > 0) { ops.push(dbDelete(table, userId, toDelete)); }
    if (toUpsert.length + toDelete.length > 0) {
      console.log(`[DB] ${table}: +${toUpsert.length} upserted, -${toDelete.length} deleted`);
    }
  }

  // ── CC tiers: delete-and-reinsert per changed account ───────────────────────
  // Simpler than diffing — just nuke and reinsert tiers for any account that changed
  const changedAccIds = new Set([
    ...(s.accounts||[]).filter(a => {
      const prev_a = (prev?.accounts||[]).find(p=>p.id===a.id);
      if(!prev_a) return true; // new account
      const prevTiers = JSON.stringify(prev_a.cbTiers||[]);
      const newTiers  = JSON.stringify(a.cbTiers||[]);
      return prevTiers !== newTiers;
    }).map(a=>a.id),
    // Also handle deleted accounts
    ...(prev?.accounts||[]).filter(p=>!(s.accounts||[]).find(a=>a.id===p.id)).map(a=>a.id),
  ]);

  if (changedAccIds.size > 0) {
    const delTierIds = [...changedAccIds];
    // Delete old tiers for changed accounts
    if (delTierIds.length > 0) {
      const { error: delErr } = await supabase.from("wm_cc_tiers")
        .delete().eq("user_id", userId).in("account_id", delTierIds);
      if (delErr) console.error("[DB] delete wm_cc_tiers:", delErr.message);
    }
    // Reinsert new tiers
    const newTierRows = ccTierRows.filter(r => changedAccIds.has(r.account_id));
    if (newTierRows.length > 0) {
      const { error: insErr } = await supabase.from("wm_cc_tiers").insert(newTierRows);
      if (insErr) console.error("[DB] insert wm_cc_tiers:", insErr.message);
      else console.log("[DB] wm_cc_tiers: reinserted", newTierRows.length, "rows for", changedAccIds.size, "accounts");
    }
  }

  // ── Holding lots: delete-and-reinsert for any changed/removed holding ────────
  // We can't diff by lot ID reliably (demerger IDs are non-deterministic),
  // so instead: for each holding that changed or disappeared, nuke ALL its lots
  // then upsert the current lots fresh.
  const prevHoldingsMap = new Map((prev?.holdings || []).map(h => [h.id, h]));
  const newHoldingsMap  = new Map((s.holdings     || []).map(h => [h.id, h]));

  // Holdings that were deleted
  const deletedHoldingIds = (prev?.holdings || [])
    .filter(h => !newHoldingsMap.has(h.id))
    .map(h => h.id);

  // Holdings whose lots changed
  const changedHoldingIds = (s.holdings || [])
    .filter(h => {
      const prev = prevHoldingsMap.get(h.id);
      if (!prev) return true; // new holding
      return JSON.stringify(h.lots || []) !== JSON.stringify(prev.lots || []);
    })
    .map(h => h.id);

  const holdingIdsToClean = [...new Set([...deletedHoldingIds, ...changedHoldingIds])];

  if (holdingIdsToClean.length > 0) {
    // Delete all old lots for these holdings
    ops.push(dbDeleteLotsByHoldingIds(userId, holdingIdsToClean));

    // Re-insert current lots for changed (not deleted) holdings
    const lotsToInsert = (s.holdings || [])
      .filter(h => changedHoldingIds.includes(h.id))
      .flatMap(h => (h.lots || []).map((lot, i) => {
        const lotId = "lot_" + h.id + "_" + (lot.txId || i);
        return { id: lotId, user_id: userId, holding_id: h.id,
                 tx_id: lot.txId || "", qty: lot.qty || 0,
                 price: lot.price || 0, date: lot.date || null };
      }));

    if (lotsToInsert.length > 0) {
      ops.push(dbUpsert("wm_holding_lots", lotsToInsert));
      console.log(`[DB] wm_holding_lots: refreshed ${holdingIdsToClean.length} holding(s), ${lotsToInsert.length} lots`);
    } else {
      console.log(`[DB] wm_holding_lots: deleted lots for ${deletedHoldingIds.length} removed holding(s)`);
    }
  }

  // ── Sub-categories: delete-and-reinsert per changed parent category ────────
  const allNewCats  = [...(s.expenseCategories||[]).map(c=>({...c,kind:"expense"})),
                       ...(s.incomeCategories ||[]).map(c=>({...c,kind:"income"}))];
  const allPrevCats = [...(prev?.expenseCategories||[]).map(c=>({...c,kind:"expense"})),
                       ...(prev?.incomeCategories ||[]).map(c=>({...c,kind:"income"}))];
  const prevCatMap  = new Map(allPrevCats.map(c=>[c.id, c]));
  const changedCatIds = allNewCats
    .filter(c => JSON.stringify(c.subCategories||[]) !== JSON.stringify(prevCatMap.get(c.id)?.subCategories||[]))
    .map(c => c.id);
  const deletedCatIds = allPrevCats.filter(c => !allNewCats.find(n=>n.id===c.id)).map(c=>c.id);
  const subCatParentsToClean = [...new Set([...changedCatIds, ...deletedCatIds])];

  if (subCatParentsToClean.length > 0) {
    ops.push((async()=>{
      const { error } = await supabase.from("wm_sub_categories")
        .delete().eq("user_id", userId).in("parent_id", subCatParentsToClean);
      if (error) console.error("[DB] delete wm_sub_categories:", error.message);
    })());
    const subRows = allNewCats
      .filter(c => changedCatIds.includes(c.id))
      .flatMap(c => (c.subCategories||[]).map(s => subCategoryToRow(s, c.id, c.kind, userId)));
    if (subRows.length > 0) {
      ops.push(dbUpsert("wm_sub_categories", subRows));
      console.log(`[DB] wm_sub_categories: refreshed ${subCatParentsToClean.length} parent(s), ${subRows.length} rows`);
    }
  }

  // Market prices: upsert changed symbols
  if (JSON.stringify(s.marketPrices) !== JSON.stringify(prev?.marketPrices)) {
    const mpRows = Object.entries(s.marketPrices || {}).map(([symbol, v]) => ({
      user_id: userId, symbol,
      current_price: parseFloat(v.current_price) || 0,
      last_updated:  v.last_updated || new Date().toISOString(),
    }));
    if (mpRows.length > 0) {
      ops.push(supabase.from("wm_market_prices")
        .upsert(mpRows, { onConflict: "user_id,symbol" })
        .then(({ error }) => { if (error) console.error("[DB] upsert wm_market_prices:", error.message); }));
    }
  }

  // FX rates: upsert all if changed
  if (JSON.stringify(s.fxRates) !== JSON.stringify(prev?.fxRates)) {
    const fxRows = Object.entries(s.fxRates || {}).map(([currency, rate]) => ({
      user_id: userId, currency, rate: parseFloat(rate) || 1,
    }));
    if (fxRows.length > 0) {
      ops.push(supabase.from("wm_fx_rates")
        .upsert(fxRows, { onConflict: "user_id,currency" })
        .then(({ error }) => { if (error) console.error("[DB] upsert wm_fx_rates:", error.message); }));
    }
  }

  await Promise.all(ops);
  _lastPushedState = s;
}

// ── One-time migration from legacy user_data JSON blob ────────────────────────
async function migrateFromLegacyBlob(userId) {
  try {
    const { data, error } = await supabase.from("user_data")
      .select("data").eq("id", userId).maybeSingle();
    if (error || !data?.data) return null;
    const clean = deduplicateState(sanitize(data.data));
    const hasData = (clean.investmentTx?.length > 0) || (clean.transactions?.length > 0) || (clean.accounts?.length > 0);
    if (!hasData) return null;
    console.log("[Migration] Migrating from legacy blob:", clean.investmentTx?.length, "trades...");
    await pushCloud(userId, clean);
    console.log("[Migration] ✅ Done.");
    return clean;
  } catch(e) {
    console.warn("[Migration] Failed:", e);
    return null;
  }
}
// ─── HELPERS ─────────────────────────────────────────────────────────────────
const uid = () => "id_" + Math.random().toString(36).slice(2,10);

function fmtCur(amount, code="INR") {
  try {
    return new Intl.NumberFormat("en-IN", {
      style:"currency", currency:code,
      minimumFractionDigits: code==="JPY" ? 0 : 2,
      maximumFractionDigits: code==="JPY" ? 0 : 2,
    }).format(amount);
  } catch { return String(amount); }
}
function toINR(amount, currency, fxRates) {
  if (!currency || currency==="INR") return amount;
  const r = fxRates?.[currency];
  return r ? amount * r : amount;
}
const fmtINR  = n => new Intl.NumberFormat("en-IN",{style:"currency",currency:"INR",minimumFractionDigits:2,maximumFractionDigits:2}).format(n);
const fmtNum  = n => new Intl.NumberFormat("en-IN",{minimumFractionDigits:2,maximumFractionDigits:2}).format(n);
const fmtDate = d => new Date(d+"T00:00:00").toLocaleDateString("en-IN",{day:"numeric",month:"short",year:"numeric"});

// ─── CREDIT CARD BILLING CYCLE LOGIC ─────────────────────────────────────────
// Returns the billing period (start/end dates) for a given CC at a given reference date.
// If billDay=15, on/after 15th the NEW cycle started on 15th of current month.
// The PAYABLE balance is all txns from previous cycle (prevStart to prevEnd).
// The OUTSTANDING balance is all txns in current cycle (since last billDay).
function getBillingCycle(billDay, refDate = new Date()) {
  const y = refDate.getFullYear();
  const m = refDate.getMonth(); // 0-indexed
  const d = refDate.getDate();

  let cycleStart, cycleEnd, prevStart, prevEnd;

  if (d >= billDay) {
    // Current cycle: billDay of this month → billDay-1 of next month
    cycleStart = new Date(y, m, billDay);
    cycleEnd   = new Date(y, m+1, billDay-1);
    // Previous cycle: billDay of last month → billDay-1 of this month
    prevStart  = new Date(y, m-1, billDay);
    prevEnd    = new Date(y, m, billDay-1);
  } else {
    // Current cycle: billDay of last month → billDay-1 of this month
    cycleStart = new Date(y, m-1, billDay);
    cycleEnd   = new Date(y, m, billDay-1);
    // Previous cycle: billDay of two months ago → billDay-1 of last month
    prevStart  = new Date(y, m-2, billDay);
    prevEnd    = new Date(y, m-1, billDay-1);
  }
  return { cycleStart, cycleEnd, prevStart, prevEnd };
}

// Returns { outstanding, payable } balances for a Credit Card account.
// outstanding = sum of CC expenses in current (open) cycle.
// payable     = sum of CC expenses in the previous (closed/billed) cycle minus payments.
function calcCCBalance(acc, transactions) {
  if (!acc.isCreditCard || !acc.billDay) {
    // Fallback to normal balance calc if not configured as CC
    return { outstanding: 0, payable: 0 };
  }
  const { cycleStart, prevStart, prevEnd } = getBillingCycle(acc.billDay);

  let outstanding = 0;
  let payable     = 0;

  // Pass 1: accumulate all expenses across billing periods
  transactions.forEach(tx => {
    if (tx.accountId !== acc.id) return;
    if (tx.type !== "expense") return;
    const txDate = new Date(tx.date+"T00:00:00");
    const netAmt = (parseFloat(tx.amount)||0) - (parseFloat(tx.refundedAmount)||0);
    if (txDate >= cycleStart) {
      outstanding += netAmt;        // current open cycle
    } else if (txDate >= prevStart && txDate <= prevEnd) {
      payable += netAmt;            // previous closed cycle → due now
    }
    // Older cycles: already paid or ignored
  });

  // Pass 2: apply payments — reduce payable (due) first, then outstanding
  // Payments = transfer TO this CC account, OR income ON this CC account (bill payment)
  transactions.forEach(tx => {
    const isPaymentTransfer = tx.type === "transfer" && tx.toAccountId === acc.id;
    const isPaymentIncome   = tx.type === "income"   && tx.accountId   === acc.id;
    if (!isPaymentTransfer && !isPaymentIncome) return;

    const amt = parseFloat(tx.amount)||0;
    if (amt <= 0) return;

    // Always reduce payable first, then outstanding (regardless of transaction date)
    const payableReduction     = Math.min(payable, amt);
    payable                   -= payableReduction;
    const remaining            = amt - payableReduction;
    outstanding                = Math.max(0, outstanding - remaining);
  });

  return { outstanding, payable };
}

// ─── BALANCE (regular accounts) ──────────────────────────────────────────────
// For CC accounts, use calcCCBalance instead.
// For regular accounts: openingBalance ± transaction effects ± trade effects.
// tradeBalanceEffects: buy → deduct from source; sell → credit to source.
function calcBalance(accountId, transactions, accounts, tradeBalanceEffects) {
  const acc     = (accounts||[]).find(a => a.id === accountId);
  const opening = parseFloat(acc?.openingBalance) || 0;

  const txBal = (transactions||[]).reduce((bal, tx) => {
    if (tx.type === "transfer") {
      if (tx.fromAccountId === accountId) return bal - (parseFloat(tx.amount)||0);
      if (tx.toAccountId   === accountId) {
        // Use toAmount if set (cross-currency transfer), else fallback to amount
        const credit = tx.toAmount != null ? parseFloat(tx.toAmount) : parseFloat(tx.amount)||0;
        return bal + credit;
      }
    } else if (tx.accountId === accountId) {
      if (tx.type === "income") return bal + (parseFloat(tx.amount)||0);
      if (tx.type === "expense") {
        // Net expense: deduct full amount; refundedAmount adds back
        const net = (parseFloat(tx.amount)||0) - (parseFloat(tx.refundedAmount)||0);
        return bal - net;
      }
    }
    return bal;
  }, opening);

  // Add trade balance effects (buy deducts from source, sell credits source)
  const tradeBal = (tradeBalanceEffects||[]).reduce((bal, eff) => {
    if (eff.accountId === accountId) return bal + eff.amount * eff.sign;
    return bal;
  }, 0);

  return txBal + tradeBal;
}

// ─── NET WORTH CALCULATOR (CENTRALIZED SERVICE) ───────────────────────────────
// Single source of truth — all views must use this function.
// Net Worth = bank + cash + wallet + holdings value (invested cost)
//           + fixed deposits (principal, active only)
//           − credit card payable balances
//
// Investment accounts (categoryId maps to a category with isInvestmentType:true)
// are EXCLUDED from the base account balance sum. Their value is represented
// entirely by the holdings array — adding both would double-count.
//
// @param accounts            - all accounts
// @param transactions        - all transactions
// @param fxRates             - FX rates map { "USD": 83.5, ... }
// @param holdings            - computed holdings (stocks + MFs)
// @param fixedDeposits       - FD array
// @param marketPrices        - unused (kept for signature compat)
// @param tradeBalanceEffects - trade balance effects (buy/sell)
// @param accountCategories   - account category definitions (needed to detect investment type)
function calcNetWorth(accounts, transactions, fxRates, holdings, fixedDeposits, marketPrices, tradeBalanceEffects, accountCategories) {
  let assets    = 0;
  let ccPayable = 0;
  const eff = tradeBalanceEffects || [];

  // Build a set of category IDs that are investment-type
  // (category objects carry isInvestmentType:true, accounts do NOT)
  const cats = accountCategories || (typeof DEFAULT !== "undefined" ? DEFAULT.accountCategories : []);
  const investmentCatIds = new Set(
    cats.filter(c => c.isInvestmentType).map(c => c.id)
  );

  accounts.forEach(acc => {
    // Respect both legacy includeInNetWorth and new include_in_networth flags
    const inNW = acc.include_in_networth !== undefined
      ? acc.include_in_networth
      : acc.includeInNetWorth;
    if (!inNW) return;

    if (acc.isCreditCard) {
      // Credit card: subtract outstanding payable from net worth
      const { payable, outstanding } = calcCCBalance(acc, transactions);
      ccPayable += toINR(payable + outstanding, acc.currency || "INR", fxRates);

    } else if (investmentCatIds.has(acc.categoryId || acc.account_type)) {
      // ── Investment account ────────────────────────────────────────────────
      // Its "value" is represented by the holdings array below.
      // Do NOT add this account's calcBalance() here — that would double-count.
      // (The tradeBalanceEffects on this account reflect money moving in/out of
      //  the account, which equals the holdings invested amount.)

    } else {
      // Bank / cash / wallet / other — add real balance
      const bal = calcBalance(acc.id, transactions, accounts, eff);
      assets += toINR(bal, acc.currency || "INR", fxRates);
    }
  });

  // ── Holdings value (stocks + mutual funds) ─────────────────────────────
  // Counted once here. Investment account balances above are skipped.
  (holdings || []).forEach(h => {
    const qty   = h.quantity || h.units || 0;
    const value = h.investedAmount || qty * (h.avgPrice || h.nav || 0);
    assets += toINR(value, h.currency || "INR", fxRates);
  });

  // ── Active fixed deposits at principal ────────────────────────────────
  (fixedDeposits || []).filter(fd => fd.status !== "closed").forEach(fd => {
    assets += toINR(parseFloat(fd.amount) || 0, fd.currency || "INR", fxRates);
  });

  return assets - ccPayable;
}

// ─── CASHBACK ENGINE ──────────────────────────────────────────────────────────
// Sums expectedCashback on all CC expense transactions grouped by card + percentage.
function calcCashbackSummary(transactions, accounts) {
  // { cardId: { cardName, icon, tiers: { "1%": { expected } }, received, pending } }
  const summary = {};
  const ccCatIds = new Set(["cat_cc"]);

  function isCCAccount(acc) {
    return acc?.isCreditCard === true ||
           acc?.account_type === "cat_cc" ||
           acc?.categoryId   === "cat_cc";
  }

  // Pass 1: expected cashback from expense txs + CC transfer (from-account is CC)
  transactions.forEach(tx => {
    if (!tx.expectedCashbackPct) return;
    // expense: accountId is the CC card
    // transfer: fromAccountId is the CC card
    const accId = tx.type === "expense" ? tx.accountId : (tx.type === "transfer" ? tx.fromAccountId : null);
    if (!accId) return;
    const acc = accounts.find(a => a.id === accId);
    if (!isCCAccount(acc)) return;
    if (!summary[acc.id]) summary[acc.id] = { cardName: acc.name, icon: acc.icon, tiers: {}, received: 0 };
    const pct = String(tx.expectedCashbackPct);
    if (!summary[acc.id].tiers[pct]) summary[acc.id].tiers[pct] = { expected: 0 };
    summary[acc.id].tiers[pct].expected += parseFloat(tx.expectedCashbackAmt)||0;
  });

  // Pass 2: received cashback from income txs tagged with cbCardId
  transactions.forEach(tx => {
    if (tx.type !== "income" || !tx.cbCardId) return;
    if (!summary[tx.cbCardId]) {
      const acc = accounts.find(a => a.id === tx.cbCardId);
      if (!acc) return;
      summary[tx.cbCardId] = { cardName: acc.name, icon: acc.icon, tiers: {}, received: 0 };
    }
    summary[tx.cbCardId].received = (summary[tx.cbCardId].received||0) + (parseFloat(tx.amount)||0);
  });

  // Pass 3: compute pending = totalExpected - received
  Object.values(summary).forEach(card => {
    const totalExpected = Object.values(card.tiers).reduce((s,t)=>s+t.expected, 0);
    card.totalExpected = totalExpected;
    card.pending = Math.max(0, totalExpected - (card.received||0));
  });

  return summary;
}

// ─── FIFO INVESTMENT LOGIC ───────────────────────────────────────────────────
// rebuildHoldings(investmentTx, existingHoldings)
//   Returns: { holdings, realizedTrades }
//
// holdings: remaining open positions (net quantity after FIFO sells)
//   • Each holding quantity = sum of remaining lot quantities
//   • avgPrice = investedAmount / remaining quantity  (reflects only unsold cost)
//
// realizedTrades: one entry per FIFO lot-match on a sell
//   { id, symbol, name, type, currency,
//     sellTxId, sellDate, sellPrice,
//     buyDate, buyPrice,
//     qty, pnl, pnlPct }
//
// FIFO rule: oldest buy lot is consumed first on every sell.
// Partial sells split the oldest lot — remaining qty stays in the lot.
function rebuildHoldings(investmentTx, existingHoldings) {
  const map = {};          // key → holding work object
  const realized = [];     // accumulates realized P&L records

  // Sort chronologically so lots are added in order
  const sorted = [...investmentTx].sort((a,b) => new Date(a.date) - new Date(b.date));

  sorted.forEach(tx => {
    if (tx.invType === "fd") return; // FDs tracked separately
    const sym = (tx.symbol || "").trim() || tx.holdingId || "unknown";
    const key = `${sym}_${tx.accountId || ""}`;

    if (!map[key]) {
      const existing = existingHoldings.find(h => h.id === tx.holdingId);
      // Guarantee id is never null/undefined — DB has NOT NULL constraint on wm_holdings.id
      const holdingId = tx.holdingId || existing?.id || ("h_" + sym + "_" + (tx.accountId || ""));
      map[key] = {
        id:             holdingId,
        symbol:         tx.symbol   || existing?.symbol || "?",
        name:           tx.name     || existing?.name   || tx.symbol || "?",
        // demerger_buy is a virtual tx but creates a REAL stock holding
        type:           (tx.type === "demerger_buy" || tx.type === "merger_buy" ? (existing?.type || "stock") : tx.invType) || existing?.type || "stock",
        accountId:      tx.accountId,
        currency:       tx.currency || existing?.currency || "INR",
        lots:           [],   // remaining buy lots
        investedAmount: 0,    // cost basis of remaining lots only
      };
    }

    const h = map[key];

    if (tx.type === "buy" || tx.type === "demerger_buy" || tx.type === "merger_buy") {
      // demerger_buy: virtual buy that credits output shares at transferred cost
      const qty   = parseFloat(tx.quantity) || 0;
      const price = (tx.type === "demerger_buy" || tx.type === "merger_buy")
        ? Math.round((parseFloat(tx.price) || 0) * 100) / 100  // round to 2dp
        : (parseFloat(tx.price) || 0);
      h.lots.push({ qty, price, date: tx.date, txId: tx.id });
      h.investedAmount += qty * price;

    } else if (tx.type === "demerger_cost_reduce") {
      // Partial demerger: reduce cost basis of parent without changing share count.
      // price = cost removed per share; quantity = eligible shares.
      const qty      = parseFloat(tx.quantity) || 0;
      const perShare = parseFloat(tx.price)    || 0;
      const totalReduction = qty * perShare;
      // Reduce cost from lots proportionally (oldest first)
      let toRemove = totalReduction;
      for (let i = 0; i < h.lots.length && toRemove > 0; i++) {
        const lot = h.lots[i];
        if (lot.qty <= 0) continue;
        const lotCost = lot.qty * lot.price;
        if (lotCost <= toRemove) {
          // Remove all cost from this lot → reduce lot price to 0
          toRemove -= lotCost;
          h.lots[i] = { ...lot, price: 0 };
        } else {
          // Partial reduction of this lot
          const newLotCost = lotCost - toRemove;
          h.lots[i] = { ...lot, price: newLotCost / lot.qty };
          toRemove = 0;
        }
      }
      h.investedAmount = Math.max(0, h.investedAmount - totalReduction);

    } else if (tx.type === "sell" || tx.type === "demerger_sell" || tx.type === "merger_sell") {
      // demerger_sell / merger_sell: virtual sells — consume lots to remove shares
      // but DO NOT record as realized P&L (these are non-taxable CA events, not real sales)
      const isVirtualSell = tx.type === "demerger_sell" || tx.type === "merger_sell";
      let remaining  = parseFloat(tx.quantity) || 0;
      const sellPrice = parseFloat(tx.price)   || 0;

      for (let i = 0; i < h.lots.length && remaining > 0; i++) {
        const lot = h.lots[i];
        if (lot.qty <= 0) continue;

        const matchedQty = Math.min(lot.qty, remaining);
        const costBasis  = lot.price;
        const pnl        = (sellPrice - costBasis) * matchedQty;
        const pnlPct     = costBasis > 0 ? ((sellPrice - costBasis) / costBasis) * 100 : 0;

        // Only push to realized for REAL sells — skip virtual CA sells (demerger/merger)
        if (!isVirtualSell) {
          realized.push({
            id:         `${tx.id}_${lot.txId || i}`,
            symbol:     h.symbol,
            name:       h.name,
            type:       h.type,
            currency:   h.currency,
            sellTxId:   tx.id,
            sellDate:   tx.date,
            sellPrice,
            buyDate:    lot.date,
            buyPrice:   costBasis,
            qty:        matchedQty,
            pnl,
            pnlPct,
          });
        }

        // Always reduce cost basis of remaining holding (lots still consumed)
        h.investedAmount -= matchedQty * costBasis;
        h.lots[i] = { ...lot, qty: lot.qty - matchedQty };
        remaining -= matchedQty;
      }
      // Remove fully consumed lots
      h.lots = h.lots.filter(l => l.qty > 0);
    }
  });

  // Build final holdings — only positions with remaining quantity
  const holdings = Object.values(map).map(h => {
    const totalQty = h.lots.reduce((s, l) => s + l.qty, 0);
    const invested  = Math.max(0, h.investedAmount);
    const avgPrice  = totalQty > 0 ? invested / totalQty : 0;
    return {
      ...h,
      quantity:       h.type !== "mf" ? totalQty : 0,
      units:          h.type === "mf" ? totalQty : 0,
      avgPrice,
      nav:            h.type === "mf" ? avgPrice : 0,
      investedAmount: invested,
    };
  }).filter(h => (h.quantity || 0) > 0 || (h.units || 0) > 0);

  return { holdings, realizedTrades: realized };
}

// Convenience: just holdings (used by ADD_INVESTMENT incremental path)
function rebuildHoldingsOnly(txList, existing) {
  return rebuildHoldings(txList, existing).holdings;
}

// Pure realized-trades builder (used by Profits tab + P&L report)
function buildRealizedTrades(investmentTx) {
  return rebuildHoldings(investmentTx, []).realizedTrades;
}

// ─── PRICE FETCH — Google Finance scrape (works from any origin) ─────────────
//
// Strategy: Scrape Google Finance HTML page for the price.
// Google Finance pages are publicly accessible and return structured HTML
// with the price embedded. We use two CORS proxy services in a waterfall.
//
// Symbol mapping → Google Finance format:
//   ITC          → NSE:ITC
//   NSE:ITC      → NSE:ITC  (passthrough)
//   MUTF_IN:xxx  → MUTF_IN:xxx (passthrough)
//   ITC.NS       → NSE:ITC
//
// CORS proxy waterfall (tested to work from localhost AND production):
//   1. allorigins.win  — most reliable, supports all origins
//   2. corsproxy.io    — good fallback
//   Timeout: 8s per proxy attempt
//
function toGoogleSymbol(raw) {
  if (!raw) return null;
  const s = raw.trim();
  // Already Google format with colon
  if (s.includes(":")) return s;
  // Yahoo-style suffix
  if (s.endsWith(".NS")) return "NSE:" + s.slice(0, -3);
  if (s.endsWith(".BO")) return "BSE:" + s.slice(0, -3);
  // Bare symbol — assume NSE
  return "NSE:" + s;
}

function toYahooSymbol(raw) {
  if (!raw) return null;
  const s = raw.trim();
  if (/\.[A-Z]{1,3}$/.test(s)) return s;
  const colonIdx = s.indexOf(":");
  if (colonIdx > 0) {
    const exchange = s.slice(0, colonIdx).toUpperCase();
    const ticker   = s.slice(colonIdx + 1);
    if (exchange === "MUTF_IN") return ticker + ".BO";
    if (exchange === "NSE")     return ticker + ".NS";
    if (exchange === "BSE")     return ticker + ".BO";
    return ticker + ".NS";
  }
  return s + ".NS";
}

// Parse price from Google Finance HTML
function parseGoogleFinancePrice(html) {
  if (!html) return null;
  // Google Finance embeds price in multiple formats; try each
  const patterns = [
    // JSON-LD / data attribute: "price":"450.25"
    /"price"\s*:\s*"?([\d,]+\.?\d*)"/,
    // The main price display div uses data-last-price
    /data-last-price="([\d.]+)"/,
    // Structured data price pattern
    /"regularMarketPrice"\s*:\s*([\d.]+)/,
    // Price in the page title or meta
    /content="[\w\s]+\s+([\d,]+\.?\d*)\s*(?:INR|₹)/,
    // YFinance-style embedded JSON
    /"currentPrice"\s*:\s*([\d.]+)/,
  ];
  for (const re of patterns) {
    const m = html.match(re);
    if (m) {
      const val = parseFloat(m[1].replace(/,/g, ""));
      if (val > 0) return val;
    }
  }
  return null;
}

async function _fetchViaProxy(url) {
  // CORS proxy waterfall — tries each in order, returns first successful response.
  // allorigins.win removed (blocked by CORS policy in many environments).
  const sig = () => {
    try { return AbortSignal.timeout(8000); } catch { return undefined; }
  };
  const proxies = [
    // 1. corsproxy.io — reliable, returns raw text
    async (u) => {
      const r = await fetch(`https://corsproxy.io/?${encodeURIComponent(u)}`, { signal: sig() });
      if (!r.ok) throw new Error("corsproxy.io " + r.status);
      return await r.text();
    },
    // 2. thingproxy.freeboard.io — good secondary
    async (u) => {
      const r = await fetch(`https://thingproxy.freeboard.io/fetch/${u}`, { signal: sig() });
      if (!r.ok) throw new Error("thingproxy " + r.status);
      return await r.text();
    },
    // 3. api.allorigins.win — kept as last resort (wraps in JSON)
    async (u) => {
      const r = await fetch(`https://api.allorigins.win/get?url=${encodeURIComponent(u)}`, { signal: sig() });
      if (!r.ok) throw new Error("allorigins " + r.status);
      const j = await r.json();
      return j.contents || "";
    },
  ];
  for (const proxy of proxies) {
    try {
      const text = await proxy(url);
      if (text && text.length > 100) return text;
    } catch (e) {
      console.warn("[PriceFetch] Proxy attempt failed:", e.message);
    }
  }
  return null;
}

// Fetch price from Google Finance for one symbol
async function _fetchGooglePrice(googleSym) {
  const url = `https://www.google.com/finance/quote/${encodeURIComponent(googleSym)}`;
  const html = await _fetchViaProxy(url);
  if (!html) return null;
  return parseGoogleFinancePrice(html);
}

// Fetch price from Yahoo Finance (more reliable numeric data)
async function _fetchYahooPrice(yahooSym) {
  const url = `https://query1.finance.yahoo.com/v8/finance/chart/${encodeURIComponent(yahooSym)}?interval=1d&range=1d`;
  const raw = await _fetchViaProxy(url);
  if (!raw) return null;
  try {
    const data = JSON.parse(raw);
    const price = data?.chart?.result?.[0]?.meta?.regularMarketPrice;
    return price && price > 0 ? parseFloat(price.toFixed(2)) : null;
  } catch { return null; }
}

async function fetchLivePrice(symbol) {
  if (!symbol) return null;
  // Try Yahoo Finance first (clean JSON, easy to parse)
  try {
    const yahooSym = toYahooSymbol(symbol);
    const yPrice = await _fetchYahooPrice(yahooSym);
    if (yPrice && yPrice > 0) return yPrice;
  } catch {}
  // Fall back to Google Finance HTML scraping
  try {
    const gSym = toGoogleSymbol(symbol);
    const gPrice = await _fetchGooglePrice(gSym);
    if (gPrice && gPrice > 0) return gPrice;
  } catch {}
  return null;
}

// Fetch prices for multiple symbols sequentially
async function fetchMultiplePrices(symbols) {
  if (!symbols || symbols.length === 0) return {};
  const result = {};
  for (let i = 0; i < symbols.length; i++) {
    try {
      const price = await fetchLivePrice(symbols[i]);
      if (price && price > 0) result[symbols[i]] = price;
    } catch {}
    if (i < symbols.length - 1) await new Promise(r => setTimeout(r, 400));
  }
  return result;
}

// ─── FD INTEREST CALCULATOR ──────────────────────────────────────────────────
function calcFDReturns(fd) {
  const principal = parseFloat(fd.amount)||0;
  const rate      = parseFloat(fd.interestRate)||0;
  const start     = new Date(fd.investedDate+"T00:00:00");
  const end       = new Date(fd.maturityDate+"T00:00:00");
  const years     = Math.max(0, (end - start) / (1000*60*60*24*365.25));
  const interest  = principal * (rate/100) * years;
  return { principal, interest: parseFloat(interest.toFixed(2)), maturityValue: parseFloat((principal+interest).toFixed(2)), years: parseFloat(years.toFixed(2)) };
}

// ─── BUILD TRADE BALANCE EFFECTS ──────────────────────────────────────────────
// Derives tradeBalanceEffects from full investmentTx array.
// Called when rebuilding from scratch (edit/delete trade).
// BUY: sign = -1 (deduct from source)
// SELL: sign = +1 (credit to source)
function buildTradeBalanceEffects(investmentTx, fixedDeposits, fxRates={}) {
  // For each trade: TWO effects — source account and investment account
  const stockEffects = [];
  (investmentTx||[])
    .filter(itx => !itx.invType?.includes("fd") && itx.invType !== "demerger_virtual")
    .forEach(itx => {
      const amt = (parseFloat(itx.quantity)||0) * (parseFloat(itx.price)||0);
      if (amt <= 0) return;
      const brokerage = parseFloat(itx.brokerage) || 0;
      // Convert trade amount to INR for source account deduction
      // Priority: fxRateAtTrade (recorded at trade time) → current fxRates → 1 (INR)
      const fxRate = parseFloat(itx.fxRateAtTrade) ||
                     (itx.currency && itx.currency !== "INR" ? (fxRates[itx.currency] || 1) : 1);
      const amtINR = amt * fxRate;
      const brokINR = brokerage * fxRate;
      // Source/bank account: deduct/credit in INR
      if (itx.sourceAccountId) {
        const srcAmt = itx.type === "buy" ? amtINR + brokINR : Math.max(0, amtINR - brokINR);
        stockEffects.push({
          id:        "eff_src_" + itx.id,
          accountId: itx.sourceAccountId,
          amount:    srcAmt,
          sign:      itx.type === "buy" ? -1 : 1,
          tradeId:   itx.id + "_src",
          date:      itx.date,
        });
      }
      // Investment account: BUY credits, SELL debits (in trade currency units)
      if (itx.accountId) {
        stockEffects.push({
          id:        "eff_inv_" + itx.id,
          accountId: itx.accountId,
          amount:    amt,
          sign:      itx.type === "buy" ? 1 : -1,
          tradeId:   itx.id + "_inv",
          date:      itx.date,
        });
      }
    });
  // FD effects: each FD deducts from its source account
  const fdEffects = (fixedDeposits||[])
    .filter(fd => fd.sourceAccountId && parseFloat(fd.amount) > 0)
    .map(fd => ({
      id:        "fdeff_" + fd.id,
      accountId: fd.sourceAccountId,
      amount:    parseFloat(fd.amount),
      sign:      -1,
      tradeId:   fd.id,
      date:      fd.investedDate || "",
      isFD:      true,
    }));
  return [...stockEffects, ...fdEffects];
}

// ─── REDUCER ─────────────────────────────────────────────────────────────────
// ─── reapplyAllCAs ────────────────────────────────────────────────────────────
// After a real tx is deleted, re-derive all virtual txs from applied CAs so
// demerger/merger lots are correctly recalculated against updated real-tx list.
function reapplyAllCAs(appliedCAs, realTxs, currentHoldings, caMasters) {
  if (!appliedCAs || appliedCAs.length === 0) return [];
  const allVirtual = [];
  // Build master lookup: "ca_auto_" + master.id → master
  const masterById = new Map((caMasters||[]).map(m => ["ca_auto_"+m.id, m]));

  for (const ca of appliedCAs) {
    const isDemerger = ca.action_type === "demerger_partial" || ca.action_type === "demerger_full";
    const isMerger   = ca.action_type === "merger";
    if (!isDemerger && !isMerger) continue;

    // Join with CA master to get ratio_from, ratio_to, new_stock, result_stocks
    const master = masterById.get(ca.id) || {};
    const parentSym  = ca.symbol || master.symbol || "";
    const recordDate = ca.record_date || ca.date || master.record_date;

    // FIFO lots for parent symbol from real txs up to record_date
    const parentTxs = realTxs
      .filter(tx => tx.symbol === parentSym && (tx.date||"") <= recordDate)
      .sort((a, b) => (a.date||"").localeCompare(b.date||""));

    const fifo = [];
    for (const tx of parentTxs) {
      if (tx.type === "buy") {
        fifo.push({ txId:tx.id, date:tx.date, remQty:parseFloat(tx.quantity)||0, price:parseFloat(tx.price)||0 });
      } else if (tx.type === "sell") {
        let q = parseFloat(tx.quantity)||0;
        for (const lot of fifo) { const c=Math.min(lot.remQty,q); lot.remQty-=c; q-=c; if(q<=0)break; }
      }
    }

    const eligLots    = fifo.filter(l => l.remQty > 0.0001);
    const totalEligQty = eligLots.reduce((s,l)=>s+l.remQty, 0);
    if (eligLots.length === 0) continue;

    const parentHolding  = (currentHoldings||[]).find(h=>h.symbol===parentSym);
    const accId    = parentHolding?.accountId || parentTxs[0]?.accountId || "";
    const currency = parentHolding?.currency  || parentTxs[0]?.currency  || "INR";

    if (isMerger) {
      const targetSym  = (master.new_stock||ca.new_stock||ca.to_symbol||"").toUpperCase();
      if (!targetSym) continue;
      const ratioFrom  = parseFloat(master.ratio_from||ca.ratio_from)||1;
      const ratioTo    = parseFloat(master.ratio_to||ca.ratio_to)||1;
      const tgtHolding   = (currentHoldings||[]).find(h=>h.symbol===targetSym&&h.accountId===accId);
      const tgtHoldingId = tgtHolding?.id||("h_mgr_"+ca.id+"_"+targetSym);

      let cumFrac=0, fracNum=0;
      for (let li=0; li<eligLots.length; li++) {
        const lot=eligLots[li];
        const exactTgt=lot.remQty*ratioTo/ratioFrom;
        const floorTgt=Math.floor(exactTgt+0.00001);
        const frac=exactTgt-floorTgt;
        const priceTgt=Math.round(lot.price*ratioFrom/ratioTo*100)/100;
        if(floorTgt>0) allVirtual.push({ id:"mgr_buy_"+ca.id+"_"+targetSym+"_"+li, type:"merger_buy",
          invType:"demerger_virtual", demergerCaId:ca.id, symbol:targetSym, name:targetSym,
          quantity:floorTgt, price:priceTgt,
          currency, date:lot.date||recordDate, accountId:accId, holdingId:tgtHoldingId,
          note:"Merger: "+floorTgt+" "+targetSym+" from "+lot.remQty+" "+parentSym+" @ ₹"+lot.price.toFixed(2) });
        cumFrac+=frac;
        const credits=Math.floor(cumFrac+0.00001);
        if(credits>=1){ fracNum++;
          allVirtual.push({ id:"mgr_buy_"+ca.id+"_"+targetSym+"_frac"+fracNum, type:"merger_buy",
            invType:"demerger_virtual", demergerCaId:ca.id, symbol:targetSym, name:targetSym,
            quantity:credits, price:priceTgt,
            currency, date:lot.date||recordDate, accountId:accId, holdingId:tgtHoldingId,
            note:"Merger fractional credit: "+credits+" "+targetSym+" (cumulative frac crossed integer)" });
          cumFrac-=credits;
        }
      }
      if (totalEligQty>0) allVirtual.push({ id:"mgr_sell_"+ca.id+"_"+parentSym,
        type:"merger_sell", invType:"demerger_virtual", demergerCaId:ca.id,
        symbol:parentSym, name:parentSym, quantity:totalEligQty, price:0,
        currency, date:recordDate, accountId:accId,
        holdingId:parentHolding?.id||("h_"+parentSym+"_"+accId), note:"Merger: "+parentSym+" dissolved" });

    } else {
      // demerger_partial / demerger_full
      // Build result_stocks from master or applied CA
      const resultStocks = (ca.result_stocks && ca.result_stocks.length > 0) ? ca.result_stocks
        : master.new_stock ? [{ symbol: master.new_stock, cost_pct: master.cost_split_new_pct,
            ratio_from: master.ratio_from, ratio_to: master.ratio_to, name: master.new_stock }]
        : [];
      if (resultStocks.length === 0) continue;

      if (ca.action_type === "demerger_full") {
        const avgPx = totalEligQty>0 ? eligLots.reduce((s,l)=>s+l.remQty*l.price,0)/totalEligQty : 0;
        allVirtual.push({ id:"dem_sell_"+ca.id, type:"demerger_sell", invType:"demerger_virtual",
          demergerCaId:ca.id, symbol:parentSym, name:parentSym, quantity:totalEligQty, price:avgPx,
          currency, date:recordDate, accountId:accId,
          holdingId:parentHolding?.id||("h_"+parentSym+"_"+accId), note:"Demerger full: "+parentSym });
      }

      for (const rs of resultStocks) {
        const outSym    = (rs.symbol||"").toUpperCase();
        const costPct   = parseFloat(rs.cost_pct)||0;
        const ratioFrom = parseFloat(rs.ratio_from)||parseFloat(ca.ratio_from)||1;
        const ratioTo   = parseFloat(rs.ratio_to)||parseFloat(ca.ratio_to)||1;
        if (!outSym) continue;

        const outHolding   = (currentHoldings||[]).find(h=>h.symbol===outSym&&h.accountId===accId);
        const outHoldingId = outHolding?.id||("h_dem_"+ca.id+"_"+outSym);

        if (ca.action_type === "demerger_partial") {
          for (const lot of eligLots) {
            const reduction = lot.remQty * lot.price * (costPct/100);
            if (reduction > 0.001) allVirtual.push({ id:"dcr_"+ca.id+"_"+outSym+"_"+lot.txId,
              type:"demerger_cost_reduce", invType:"demerger_virtual", demergerCaId:ca.id,
              symbol:parentSym, quantity:lot.remQty, price:lot.price*(costPct/100),
              currency, date:recordDate, accountId:accId,
              holdingId:parentHolding?.id||("h_"+parentSym+"_"+accId), lotDate:lot.date,
              note:"Demerger cost adj: lot "+lot.date+" "+lot.remQty+"×"+lot.price.toFixed(2) });
          }
        }

        // Zerodha-matching demerger algorithm — same as ADD_CORPORATE_ACTION reducer:
        // Large lots flush at pure lot price with lot.date; small lots pool at WAVG.
        let bNum=0, poolQty=0, poolCost=0;
        const emitDemBuy = (price, date) => {
          bNum++;
          allVirtual.push({ id:"dem_buy_"+ca.id+"_"+outSym+"_b"+bNum, type:"demerger_buy",
            invType:"demerger_virtual", demergerCaId:ca.id, symbol:outSym, name:rs.name||outSym,
            quantity:Math.floor(ratioTo), price:Math.round((price*costPct/100)*ratioFrom/Math.max(1,ratioTo)*100)/100,
            currency, date:date||recordDate, accountId:accId, holdingId:outHoldingId,
            note:"Demerger: "+Math.floor(ratioTo)+" "+outSym+" from "+ratioFrom+" "+parentSym+" (lot "+date+")" });
        };
        const flushPool = (date) => {
          while (poolQty >= ratioFrom-0.0001) {
            const wavg = poolCost/poolQty;
            emitDemBuy(wavg, date);
            poolCost -= ratioFrom*wavg; poolQty -= ratioFrom;
            if (poolQty<0.0001){poolQty=0;poolCost=0;}
          }
        };
        for (const lot of eligLots) {
          if (lot.remQty >= ratioFrom) {
            let lotRem = lot.remQty;
            while (lotRem >= ratioFrom-0.0001) {
              emitDemBuy(lot.price, lot.date);
              lotRem -= ratioFrom;
            }
            poolQty+=lotRem; poolCost+=lotRem*lot.price;
            flushPool(lot.date);
          } else {
            poolQty+=lot.remQty; poolCost+=lot.remQty*lot.price;
            flushPool(lot.date);
          }
        }
      }
    }
  }
  return allVirtual;
}

function reducer(rawState, action) {
  const s = sanitize(rawState);
  // Guard: React internals or Supabase realtime may fire with undefined action
  if (!action || typeof action.type !== "string") return s;
  switch (action.type) {
    case "SET": {
      const raw = sanitize(action.payload);
      // Deduplicate holdings on SET (e.g. from old DB data)
      if (raw.holdings && raw.holdings.length > 0) {
        const hMap = new Map();
        for (const h of raw.holdings) {
          const key = (h.symbol||"") + "_" + (h.accountId||"");
          const prev = hMap.get(key);
          if (!prev || (h.investedAmount||0) > (prev.investedAmount||0)) hMap.set(key, h);
        }
        if (hMap.size < raw.holdings.length) {
          console.log(`[State] Deduplicated ${raw.holdings.length - hMap.size} duplicate holding(s) on SET`);
          return { ...raw, holdings: [...hMap.values()] };
        }
      }
      return raw;
    }

    // ── Transactions ─────────────────────────────────────────────────────────
    // Transactions are INCOME or EXPENSE only (transfer preserved for UI compat).
    // is_refund flag marks refund-type income transactions.
    case "ADD_TX":      return { ...s, transactions: [...s.transactions, action.payload] };

    case "EDIT_TX":     return { ...s, transactions: s.transactions.map(t =>
                          t.id === action.payload.id ? action.payload : t) };

    case "DELETE_TX":   return { ...s, transactions: s.transactions.filter(t =>
                          t.id !== action.payload) };

    // Apply a refund: link income tx to expense tx, update refundedAmount
    case "APPLY_REFUND": {
      const { expenseId, refundAmt } = action.payload;
      return {
        ...s,
        transactions: s.transactions.map(t => {
          if (t.id !== expenseId) return t;
          const prev = parseFloat(t.refundedAmount)||0;
          const next = Math.min(prev + refundAmt, parseFloat(t.amount)||0);
          return {
            ...t,
            refundedAmount: next,
            is_refund: true,
            isRefunded: next >= (parseFloat(t.amount)||0),
          };
        }),
      };
    }

    // ── Accounts ─────────────────────────────────────────────────────────────
    case "ADD_ACCOUNT":  return { ...s, accounts: [...s.accounts, sanitizeAccount(action.payload)] };
    case "EDIT_ACCOUNT": return { ...s, accounts: s.accounts.map(a =>
                           a.id === action.payload.id ? sanitizeAccount(action.payload) : a) };

    // ── Account categories (fully CRUD) ──────────────────────────────────────
    case "ADD_ACC_CAT":  return { ...s, accountCategories: [...s.accountCategories, action.payload] };
    case "EDIT_ACC_CAT": return { ...s, accountCategories: s.accountCategories.map(c =>
                           c.id === action.payload.id ? action.payload : c) };
    case "DEL_ACC_CAT":  return { ...s, accountCategories: s.accountCategories.filter(c =>
                           c.id !== action.payload) };

    // ── Transaction categories (with subCategories[] support) ─────────────────
    case "ADD_EXP_CAT":  return { ...s, expenseCategories: [...s.expenseCategories, action.payload] };
    case "UPD_EXP_CAT":  return { ...s, expenseCategories: s.expenseCategories.map(c =>
                           c.id === action.payload.id ? action.payload : c) };
    case "DEL_EXP_CAT":  return { ...s, expenseCategories: s.expenseCategories.filter(c => c.id !== action.payload) };
    case "ADD_INC_CAT":  return { ...s, incomeCategories:  [...s.incomeCategories,  action.payload] };
    case "UPD_INC_CAT":  return { ...s, incomeCategories:  s.incomeCategories.map(c =>
                           c.id === action.payload.id ? action.payload : c) };
    case "DEL_INC_CAT":  return { ...s, incomeCategories:  s.incomeCategories.filter(c =>  c.id !== action.payload) };

    // ── FX ───────────────────────────────────────────────────────────────────
    case "SET_FX":       return { ...s, fxRates: action.payload };

    // ── Accounts – hard delete (only if no transactions touch it) ─────────────
    case "DELETE_ACCOUNT": return { ...s, accounts: s.accounts.filter(a => a.id !== action.payload) };

    // ── Stocks Master Table ────────────────────────────────────────────────────
    // ADD_STOCK: { id, symbol, name, type, exchange }
    case "ADD_STOCK":    return { ...s, stocks: [...(s.stocks||[]), action.payload] };
    case "EDIT_STOCK":   return { ...s, stocks: (s.stocks||[]).map(st => st.id===action.payload.id ? action.payload : st) };
    case "DELETE_STOCK": return { ...s, stocks: (s.stocks||[]).filter(st => st.id !== action.payload) };
    // RENAME_STOCK: rename symbol in stocks table + update all holdings + investmentTx
    case "RENAME_STOCK": {
      const { oldSymbol, newSymbol, newName } = action.payload;
      return {
        ...s,
        stocks: (s.stocks||[]).map(st => st.symbol===oldSymbol ? {...st, symbol:newSymbol, name:newName||st.name} : st),
        holdings: (s.holdings||[]).map(h => h.symbol===oldSymbol ? {...h, symbol:newSymbol, name:newName||h.name} : h),
        investmentTx: (s.investmentTx||[]).map(t => t.symbol===oldSymbol ? {...t, symbol:newSymbol} : t),
        marketPrices: (() => {
          const mp = {...(s.marketPrices||{})};
          if (mp[oldSymbol]) { mp[newSymbol]=mp[oldSymbol]; delete mp[oldSymbol]; }
          return mp;
        })(),
      };
    }

    // ── Market Prices ──────────────────────────────────────────────────────────
    // UPDATE_MARKET_PRICE: { symbol, current_price, last_updated }
    // Stores fetched prices separately from trade prices.
    case "UPDATE_MARKET_PRICE": {
      const { symbol, current_price, last_updated } = action.payload;
      return {
        ...s,
        marketPrices: {
          ...s.marketPrices,
          [symbol]: { current_price, last_updated: last_updated || new Date().toISOString() },
        },
      };
    }

    // ── Corporate Actions ──────────────────────────────────────────────────────
    // ADD_CORPORATE_ACTION: { id, symbol, action_type, ratio, date, note, ... }
    // action_type: stock_split | bonus | reverse_split | dividend | stock_name_change
    //              | merger | demerger_partial | demerger_full
    case "ADD_CORPORATE_ACTION": {
      const ca  = action.payload;
      const newActions = [...s.corporateActions, ca];
      let holdings = [...s.holdings];

      if (ca.action_type === "stock_split" || ca.action_type === "bonus") {
        holdings = holdings.map(h => {
          if (h.symbol !== ca.symbol) return h;
          const ratio  = parseFloat(ca.ratio) || 1;
          const newQty = (h.quantity || h.units || 0) * ratio;
          const newAvg = (h.avgPrice || h.nav || 0) / ratio;
          return { ...h, quantity: h.type !== "mf" ? newQty : 0,
                         units:    h.type === "mf" ? newQty : 0,
                         avgPrice: newAvg, nav: newAvg };
        });

      } else if (ca.action_type === "reverse_split") {
        holdings = holdings.map(h => {
          if (h.symbol !== ca.symbol) return h;
          const ratio  = parseFloat(ca.ratio) || 1;
          const newQty = (h.quantity || h.units || 0) / ratio;
          const newAvg = (h.avgPrice || h.nav || 0) * ratio;
          return { ...h, quantity: h.type !== "mf" ? newQty : 0,
                         units:    h.type === "mf" ? newQty : 0,
                         avgPrice: newAvg, nav: newAvg };
        });

      } else if (ca.action_type === "stock_name_change") {
        const { new_symbol, new_name } = ca;
        holdings = holdings.map(h => {
          if (h.symbol !== ca.symbol) return h;
          return { ...h, symbol: new_symbol || h.symbol, name: new_name || h.name };
        });

      } else if (ca.action_type === "demerger_partial" || ca.action_type === "demerger_full" || ca.action_type === "merger") {
        // ── DEMERGER via VIRTUAL TRANSACTIONS (per-lot FIFO) ──────────────────
        //
        // For each result stock:
        //   1. Run FIFO on parent trades up to record_date to get remaining lots
        //   2. Per lot: adjust parent cost by parent_pct; allocate new_pct to new stock
        //   3. Group lots into batches of ratio_from shares → 1 new share each
        //   4. One demerger_buy tx per batch (preserving lot-level cost basis)
        //   5. One demerger_cost_reduce per original eligible ITC lot (partial)
        //   6. Fractional remainder shares → cash back to account balance (future)
        //
        // Example: ITC→ITC Hotels 10:1, 13.51% cost
        //   47 eligible shares (5 lots)
        //   → 4 ITC Hotels shares (floor(47/10)), each priced from their lot group
        //   → remaining 7 shares: value added to residual note

        const recordDate  = ca.record_date || ca.date;
        const parentSym   = ca.symbol;
        const parentHolding = (s.holdings || []).find(h => h.symbol === parentSym);
        if (!parentHolding) return { ...s, corporateActions: newActions };

        const accId    = parentHolding.accountId || "";
        const currency = parentHolding.currency  || "INR";

        // ── Step 1: FIFO on eligible parent trades → remaining lots ─────────────
        // Filter buy/sell trades for parent up to record_date, sort chronologically
        const parentTrades = (s.investmentTx || [])
          .filter(tx => tx.symbol === parentSym
                     && tx.date <= recordDate
                     && !tx.invType?.includes("virtual"))
          .sort((a, b) => new Date(a.date) - new Date(b.date));

        // Build FIFO lot queue from buy trades
        const fifoLots = [];
        for (const tx of parentTrades) {
          if (tx.type === "buy") {
            fifoLots.push({
              txId:   tx.id,
              date:   tx.date,
              origQty: parseFloat(tx.quantity) || 0,
              remQty:  parseFloat(tx.quantity) || 0,
              price:   parseFloat(tx.price)    || 0,
            });
          } else if (tx.type === "sell") {
            let toConsume = parseFloat(tx.quantity) || 0;
            for (const lot of fifoLots) {
              if (toConsume <= 0) break;
              const consumed = Math.min(lot.remQty, toConsume);
              lot.remQty   -= consumed;
              toConsume    -= consumed;
            }
          }
        }

        // Keep only lots with remaining shares
        const eligLots = fifoLots.filter(l => l.remQty > 0.0001);
        const totalEligQty = eligLots.reduce((s, l) => s + l.remQty, 0);

        if (totalEligQty <= 0 || eligLots.length === 0) {
          return { ...s, corporateActions: newActions };
        }

        // ── Guard: remove any existing virtual txs for this CA (prevents duplicates on re-apply) ──
        const existingVirtualIds = new Set(
          (s.investmentTx || [])
            .filter(tx => tx.demergerCaId === ca.id)
            .map(tx => tx.id)
        );
        const cleanTxsBase = existingVirtualIds.size > 0
          ? (s.investmentTx || []).filter(tx => !existingVirtualIds.has(tx.id))
          : (s.investmentTx || []);

        const virtualTxs = [];

        // ── DEMERGER-specific logic (partial or full) ──────────────────────────
        if (ca.action_type === "demerger_partial" || ca.action_type === "demerger_full") {
        // ── Step 2: For FULL demerger, inject virtual sell to zero-out parent ───
        if (ca.action_type === "demerger_full") {
          const eligCostFull = eligLots.reduce((s, l) => s + l.remQty * l.price, 0);
          const avgPxFull    = totalEligQty > 0 ? eligCostFull / totalEligQty : 0;
          virtualTxs.push({
            id:           "dem_sell_" + ca.id,
            type:         "demerger_sell",
            invType:      "demerger_virtual",
            demergerCaId: ca.id,
            symbol:       parentSym,
            name:         parentHolding.name || parentSym,
            quantity:     totalEligQty,
            price:        avgPxFull,
            currency, date: ca.date, accountId: accId,
            holdingId:    parentHolding.id || ("h_" + parentSym + "_" + accId),
            note: `Demerger (full): ${parentSym} → ${(ca.result_stocks||[]).map(r=>r.symbol).join(", ")}`,
          });
        }

        // ── Step 3: Per result stock — generate per-lot cost-reduce + grouped buys ─
        (ca.result_stocks || []).forEach(rs => {
          const outSym     = rs.symbol.toUpperCase();
          const outName    = rs.name || outSym;
          const outAccId   = rs.accountId || accId;
          const costPct    = parseFloat(rs.cost_pct)    || 0;   // % of each lot's cost → new stock
          const parentPct  = 100 - costPct;                      // % kept by parent

          // ratio_from parent shares : ratio_to new shares  (e.g. 10 ITC : 1 ITC Hotels)
          const ratioFrom  = parseFloat(rs.ratio_from) || parseFloat(rs.share_ratio) || 1;
          const ratioTo    = parseFloat(rs.ratio_to)   || 1;

          // ── Step 3a: Per eligible lot → one demerger_cost_reduce on parent ────
          // (partial demerger only — reduces parent's cost basis per lot)
          if (ca.action_type === "demerger_partial") {
            eligLots.forEach((lot, i) => {
              const lotCostToRemove = lot.remQty * lot.price * (costPct / 100);
              const perShareRemoval = lot.remQty > 0 ? lotCostToRemove / lot.remQty : 0;
              virtualTxs.push({
                id:           `dem_cost_${ca.id}_${outSym}_lot${i}`,
                type:         "demerger_cost_reduce",
                invType:      "demerger_virtual",
                demergerCaId: ca.id,
                symbol:       parentSym,
                name:         parentHolding.name || parentSym,
                quantity:     lot.remQty,
                price:        perShareRemoval,
                lotDate:      lot.date,          // ← which source lot this reduces
                currency, date: ca.date, accountId: accId,
                holdingId:    parentHolding.id || ("h_" + parentSym + "_" + accId),
                note: `Demerger cost adjust: lot ${lot.date} ${lot.remQty}×₹${lot.price.toFixed(2)} → ${costPct}% to ${outSym}`,
              });
            });
          }

          // ── Step 3b: Group eligible lots into batches of ratioFrom shares ─────
          // Each batch of ratioFrom parent shares → ratioTo new shares
          //
          // ── Zerodha-matching algorithm ────────────────────────────────────────────
          // Rule: when a lot has qty >= ratioFrom (e.g. 12 shares bought at once):
          //   1. First flush complete batches using ONLY this lot's price (pure lot)
          //   2. Then combine remaining lot shares + prior pool → flush at WAVG
          // When a lot has qty < ratioFrom: accumulate into pool, flush at WAVG as usual.
          // This matches Zerodha's demerger cost basis exactly.
          let batchNum = 0;
          let poolQty  = 0;
          let poolCost = 0;

          // Use the existing output holding's ID if it exists — avoids duplicate DB rows
          const outHolding = (s.holdings||[]).find(h => h.symbol === outSym && h.accountId === outAccId);
          const outHoldingId = outHolding?.id || `h_dem_${ca.id}_${outSym}_${outAccId}`;

          const emitBatch = (price, date) => {
            const newSharesPerBatch = Math.floor(ratioTo);
            const pricePerNewShare  = (price * costPct / 100) * ratioFrom / Math.max(1, ratioTo);
            batchNum++;
            virtualTxs.push({
              id:           `dem_buy_${ca.id}_${outSym}_b${batchNum}`,
              type:         "demerger_buy",
              invType:      "demerger_virtual",
              demergerCaId: ca.id,
              symbol:       outSym,
              name:         outName,
              quantity:     newSharesPerBatch,
              price:        Math.round(pricePerNewShare * 100) / 100,
              currency, date: date || ca.date, accountId: outAccId,
              holdingId:    outHoldingId,
              note: `Demerger: ${newSharesPerBatch} ${outSym} from ${ratioFrom} ${parentSym} (ratio ${ratioFrom}:${ratioTo}, ${costPct}% cost)`,
            });
          };

          const flushPoolWavg = (date) => {
            while (poolQty >= ratioFrom - 0.0001) {
              const wavg = poolCost / poolQty;
              emitBatch(wavg, date);
              poolCost -= ratioFrom * wavg;
              poolQty  -= ratioFrom;
              if (poolQty < 0.0001) { poolQty = 0; poolCost = 0; }
            }
          };

          for (const lot of eligLots) {
            if (lot.remQty >= ratioFrom) {
              // Large lot: first flush complete batches at pure lot price
              let lotRem = lot.remQty;
              while (lotRem >= ratioFrom - 0.0001) {
                emitBatch(lot.price, lot.date);
                lotRem -= ratioFrom;
              }
              // Then merge remaining lot shares into pool and flush WAVG if possible
              poolQty  += lotRem;
              poolCost += lotRem * lot.price;
              flushPoolWavg(lot.date);
            } else {
              // Small lot: accumulate into pool, flush at WAVG
              poolQty  += lot.remQty;
              poolCost += lot.remQty * lot.price;
              flushPoolWavg(lot.date);
            }
          }

          // Fractional remainder (< ratioFrom shares left) — note it but don't generate shares
          if (poolQty > 0.0001) {
            // These shares don't complete a full batch — their allocated cost is residual
            // Record as a zero-qty informational tx (won't affect holdings)
            const residualCost = poolCost;
            virtualTxs.push({
              id:           `dem_residual_${ca.id}_${outSym}`,
              type:         "demerger_cost_reduce",
              invType:      "demerger_virtual",
              demergerCaId: ca.id,
              symbol:       parentSym,
              name:         parentHolding.name || parentSym,
              quantity:     0,   // zero qty — won't affect holdings math
              price:        0,
              currency, date: ca.date, accountId: accId,
              holdingId:    parentHolding.id || ("h_" + parentSym + "_" + accId),
              note: `Demerger residual: ${poolQty.toFixed(4)} ${parentSym} shares (< ${ratioFrom}:${ratioTo} ratio) — ₹${residualCost.toFixed(2)} allocated cost retained in ${parentSym}`,
            });
          }
        });

        } // end demerger-specific

        // ── MERGER handler ────────────────────────────────────────────────────
        if (ca.action_type === "merger") {
          // parentSym, mgrRatioFrom, mgrRatioTo, recordDate, accId, currency are set in outer scope
          const targetSym   = (ca.new_stock || "").toUpperCase();
          const mgrRatioFrom = parseFloat(ca.ratio_from) || 1;
          const mgrRatioTo   = parseFloat(ca.ratio_to)   || 1;

          if (targetSym) {
            // Use outer-scope accId/currency (already derived from parentHolding)
            // Collect source txs via FIFO up to record_date
            const sourceTxs = (cleanTxsBase)
              .filter(tx => tx.symbol === parentSym
                && !tx.invType?.includes("virtual")
                && (tx.date || "") <= recordDate)
              .sort((a, b) => (a.date||"").localeCompare(b.date||""));

            // Build FIFO lots
            const fifoLots = [];
            for (const tx of sourceTxs) {
              if (tx.type === "buy" || tx.type === "demerger_buy" || tx.type === "merger_buy") {
                fifoLots.push({ date: tx.date, qty: parseFloat(tx.quantity)||0, price: parseFloat(tx.price)||0 });
              } else if (tx.type === "sell" || tx.type === "demerger_sell" || tx.type === "merger_sell") {
                let sellQty = parseFloat(tx.quantity)||0;
                for (const lot of fifoLots) {
                  const used = Math.min(lot.qty, sellQty);
                  lot.qty -= used; sellQty -= used;
                  if (sellQty <= 0) break;
                }
              }
            }
            const eligibleLots    = fifoLots.filter(l => l.qty > 0.0001);
            const totalSourceQty  = eligibleLots.reduce((s, l) => s + l.qty, 0);

            // Find/create target holding ID
            const tgtHolding   = (s.holdings||[]).find(h => h.symbol === targetSym && h.accountId === accId);
            const tgtHoldingId = tgtHolding?.id || ("h_mgr_" + ca.id + "_" + targetSym);

            // Per-lot direct mapping (Zerodha method):
            // Each source buy lot → one target lot at transferred cost basis.
            //   qty_new   = floor(qty_old × ratioTo / ratioFrom)
            //   price_new = price_old × ratioFrom / ratioTo
            // Fractional shares: Zerodha uses a CUMULATIVE running total across all lots.
            // When the running total crosses an integer, 1 share is credited as a new lot
            // at the cost basis of the lot that triggered the crossover.
            // Remaining fraction at the end is cash-settled by registrar (not tracked here).
            let cumulativeFrac = 0;
            let fracCreditNum  = 0;

            for (let li = 0; li < eligibleLots.length; li++) {
              const lot         = eligibleLots[li];
              const exactTgtQty = lot.qty * mgrRatioTo / mgrRatioFrom;
              const floorTgtQty = Math.floor(exactTgtQty + 0.00001);
              const fracQty     = exactTgtQty - floorTgtQty;
              const pricePerTgt = lot.price * mgrRatioFrom / mgrRatioTo;

              if (floorTgtQty > 0) {
                virtualTxs.push({
                  id:           "mgr_buy_" + ca.id + "_" + targetSym + "_" + li,
                  type:         "merger_buy", invType: "demerger_virtual", demergerCaId: ca.id,
                  symbol:       targetSym, name: targetSym,
                  quantity:     floorTgtQty,
                  price:        Math.round(pricePerTgt * 100) / 100,
                  currency, date: lot.date, accountId: accId, holdingId: tgtHoldingId,
                  note: "Merger: " + floorTgtQty + " " + targetSym + " from " + lot.qty + " " + parentSym + " @ ₹" + lot.price.toFixed(2),
                });
              }

              // Accumulate fractional remainder; credit 1 share per integer crossed
              cumulativeFrac += fracQty;
              const fracCredits = Math.floor(cumulativeFrac + 0.00001);
              if (fracCredits >= 1) {
                fracCreditNum++;
                virtualTxs.push({
                  id:           "mgr_buy_" + ca.id + "_" + targetSym + "_frac" + fracCreditNum,
                  type:         "merger_buy", invType: "demerger_virtual", demergerCaId: ca.id,
                  symbol:       targetSym, name: targetSym,
                  quantity:     fracCredits,
                  price:        Math.round(pricePerTgt * 100) / 100, // cost basis of triggering lot
                  currency, date: lot.date, accountId: accId, holdingId: tgtHoldingId,
                  note: "Merger fractional credit: " + fracCredits + " " + targetSym + " (cumulative frac crossed integer)",
                });
                cumulativeFrac -= fracCredits;
              }
              // Remaining cumulativeFrac < 1 at end → cash-settled by registrar, not tracked
            }
            // Dissolve source stock entirely
            if (totalSourceQty > 0) {
              virtualTxs.push({
                id:           "mgr_sell_" + ca.id + "_" + parentSym,
                type:         "merger_sell", invType: "demerger_virtual", demergerCaId: ca.id,
                symbol:       parentSym, name: parentSym,
                quantity:     totalSourceQty, price: 0,
                currency, date: recordDate, accountId: accId,
                holdingId:    parentHolding?.id || ("h_" + parentSym + "_" + accId),
                note: "Merger: " + parentSym + " dissolved → " + targetSym + " (" + mgrRatioFrom + ":" + mgrRatioTo + ")",
              });
            }
          }
        }

        // ── Rebuild entire holdings from all txs + new virtual txs ─────────────
        const allTxs = [...cleanTxsBase, ...virtualTxs];
        const { holdings: rebuiltHoldings } = rebuildHoldings(allTxs, []);
        const newEffects = buildTradeBalanceEffects(allTxs, s.fixedDeposits || [], s.fxRates || {});

        return {
          ...s,
          corporateActions:    newActions,
          investmentTx:        allTxs,
          holdings:            rebuiltHoldings,
          tradeBalanceEffects: newEffects,
        };
      }

      // dividend: income only — handled in UI
      return { ...s, corporateActions: newActions, holdings };
    }

    // ── Delete Corporate Action (reverses holdings effect) ───────────────────
    case "DELETE_CORPORATE_ACTION": {
      const caId = action.payload;
      const ca = (s.corporateActions||[]).find(c => c.id===caId);
      if (!ca) return s;
      const newActions = s.corporateActions.filter(c => c.id!==caId);
      let holdings = [...s.holdings];

      if (ca.action_type === "stock_split" || ca.action_type === "bonus") {
        const ratio = parseFloat(ca.ratio)||1;
        holdings = holdings.map(h => {
          if (h.symbol !== ca.symbol) return h;
          const newQty = (h.quantity||h.units||0) / ratio;
          const newAvg = (h.avgPrice||h.nav||0) * ratio;
          return { ...h, quantity: h.type!=="mf"?newQty:0, units: h.type==="mf"?newQty:0, avgPrice:newAvg, nav:newAvg };
        });

      } else if (ca.action_type === "reverse_split") {
        const ratio = parseFloat(ca.ratio)||1;
        holdings = holdings.map(h => {
          if (h.symbol !== ca.symbol) return h;
          const newQty = (h.quantity||h.units||0) * ratio;
          const newAvg = (h.avgPrice||h.nav||0) / ratio;
          return { ...h, quantity: h.type!=="mf"?newQty:0, units: h.type==="mf"?newQty:0, avgPrice:newAvg, nav:newAvg };
        });

      } else if (ca.action_type === "stock_name_change") {
        holdings = holdings.map(h => {
          if (h.symbol !== ca.new_symbol) return h;
          return { ...h, symbol: ca.symbol, name: ca.old_name||ca.symbol };
        });

      } else if (ca.action_type === "merger" || ca.action_type === "demerger_partial" || ca.action_type === "demerger_full") {
        // ── UNDO DEMERGER — remove virtual txs and rebuild holdings ─────────────
        // Virtual txs are tagged with { demergerCaId: ca.id }.
        // Remove all of them, then rebuild holdings from the clean ledger.
        const cleanTxs = (s.investmentTx || []).filter(
          tx => tx.demergerCaId !== ca.id
        );
        const { holdings: rebuiltHoldings } = rebuildHoldings(cleanTxs, []);
        const newEffects = buildTradeBalanceEffects(cleanTxs, s.fixedDeposits || [], s.fxRates || {});
        return {
          ...s,
          corporateActions:    newActions,
          investmentTx:        cleanTxs,
          holdings:            rebuiltHoldings,
          tradeBalanceEffects: newEffects,
        };
      }

      return { ...s, corporateActions: newActions, holdings };
    }
    // ── Bulk Delete Holdings ──────────────────────────────────────────────────
    case "BULK_DELETE_HOLDINGS": {
      const symbols = action.payload;
      const newTxs     = s.investmentTx.filter(t => !symbols.includes(t.symbol));
      // Preserve applied CA records — deleting trades must not re-trigger CA banner on re-import.
      // CA records are user-level DB records; they stay until explicitly undone via CA management.
      const newActions = s.corporateActions; // intentionally NOT filtered by symbol
      const { holdings: newHoldings } = rebuildHoldings(newTxs, s.holdings);
      const newEffects = buildTradeBalanceEffects(newTxs, s.fixedDeposits, s.fxRates || {});
      return { ...s, holdings: newHoldings, investmentTx: newTxs, corporateActions: newActions, tradeBalanceEffects: newEffects };
    }

    // ── Investments (full FIFO-aware) ─────────────────────────────────────────
    // ADD_INVESTMENT: { newHolding, itx }
    // BUY:  deducts trade value from sourceAccountId via tradeBalanceEffect
    // SELL: credits trade value to sourceAccountId via tradeBalanceEffect
    // Holdings are updated incrementally here (not rebuilt from scratch).
    case "ADD_INVESTMENT": {
      const { newHolding, itx } = action.payload;
      const tradeAmt = (parseFloat(itx.quantity)||0) * (parseFloat(itx.price)||0);

      // Trade balance effects:
      // BUY:  source account (bank) -tradeAmt, investment account +tradeAmt
      // SELL: investment account -tradeAmt, source account (bank) +tradeAmt
      const tradeEffects = [...s.tradeBalanceEffects];
      if (tradeAmt > 0) {
        if (itx.sourceAccountId) {
          const brok = parseFloat(itx.brokerage) || 0;
          const srcAmt = itx.type === "buy" ? tradeAmt + brok : Math.max(0, tradeAmt - brok);
          tradeEffects.push({
            id:        uid(),
            accountId: itx.sourceAccountId,
            amount:    srcAmt,
            sign:      itx.type === "buy" ? -1 : 1,
            tradeId:   itx.id + "_src",
            date:      itx.date,
          });
        }
        if (itx.accountId) {
          tradeEffects.push({
            id:        uid(),
            accountId: itx.accountId,
            amount:    tradeAmt,
            sign:      itx.type === "buy" ? 1 : -1,
            tradeId:   itx.id + "_inv",
            date:      itx.date,
          });
        }
      }

      // Incremental holdings update (FIFO for sells)
      let holdings = [...s.holdings];
      const existingIdx = holdings.findIndex(h =>
        h.id === (newHolding?.id || itx.holdingId) ||
        (h.symbol === itx.symbol && h.accountId === itx.accountId)
      );

      if (itx.type === "buy") {
        if (existingIdx >= 0) {
          // Update existing holding incrementally
          const h = holdings[existingIdx];
          const newQty = (h.quantity || h.units || 0) + (parseFloat(itx.quantity)||0);
          const newInvested = (h.investedAmount || 0) + tradeAmt;
          const newAvg = newQty > 0 ? newInvested / newQty : 0;
          const newLots = [...(h.lots||[]), { qty: parseFloat(itx.quantity)||0, price: parseFloat(itx.price)||0, date: itx.date, txId: itx.id }];
          holdings[existingIdx] = {
            ...h,
            lots: newLots,
            quantity: h.type !== "mf" ? newQty : 0,
            units:    h.type === "mf" ? newQty : 0,
            avgPrice: newAvg, nav: h.type === "mf" ? newAvg : h.nav,
            investedAmount: newInvested,
          };
        } else if (newHolding) {
          // Brand new holding
          const qty = parseFloat(itx.quantity)||0;
          holdings.push({
            ...newHolding,
            lots: [{ qty, price: parseFloat(itx.price)||0, date: itx.date, txId: itx.id }],
            quantity: newHolding.type !== "mf" ? qty : 0,
            units:    newHolding.type === "mf" ? qty : 0,
            avgPrice: parseFloat(itx.price)||0,
            investedAmount: tradeAmt,
          });
        }
      } else if (itx.type === "sell" && existingIdx >= 0) {
        // FIFO sell on existing holding
        const h = holdings[existingIdx];
        let lots = [...(h.lots||[])].sort((a,b) => new Date(a.date) - new Date(b.date));
        let remaining = parseFloat(itx.quantity)||0;
        let investedReduction = 0;
        for (let i = 0; i < lots.length && remaining > 0; i++) {
          if (lots[i].qty <= remaining) {
            investedReduction += lots[i].qty * lots[i].price;
            remaining -= lots[i].qty;
            lots[i] = { ...lots[i], qty: 0 };
          } else {
            investedReduction += remaining * lots[i].price;
            lots[i] = { ...lots[i], qty: lots[i].qty - remaining };
            remaining = 0;
          }
        }
        lots = lots.filter(l => l.qty > 0);
        const newQty = lots.reduce((s,l) => s + l.qty, 0);
        const newInvested = Math.max(0, (h.investedAmount||0) - investedReduction);
        const newAvg = newQty > 0 ? newInvested / newQty : 0;
        if (newQty <= 0) {
          holdings.splice(existingIdx, 1); // fully sold out
        } else {
          holdings[existingIdx] = {
            ...h, lots,
            quantity: h.type !== "mf" ? newQty : 0,
            units:    h.type === "mf" ? newQty : 0,
            avgPrice: newAvg, nav: h.type === "mf" ? newAvg : h.nav,
            investedAmount: newInvested,
          };
        }
      }

      return {
        ...s,
        holdings,
        investmentTx:        [...s.investmentTx, itx],
        tradeBalanceEffects: tradeEffects,
      };
    }

    case "EDIT_INVESTMENT_TX": {
      if (!action.payload?.id) return s;
      // MERGE payload into existing tx — never replace entirely (would wipe all fields)
      const newTxs = s.investmentTx.map(t => t.id===action.payload.id ? {...t, ...action.payload} : t);
      const { holdings: rebuilt } = rebuildHoldings(newTxs, s.holdings);
      const stockEffects = buildTradeBalanceEffects(newTxs, [], s.fxRates || {});
      const fdEffects = s.tradeBalanceEffects.filter(e => e.isFD);
      return { ...s, investmentTx: newTxs, holdings: rebuilt, tradeBalanceEffects: [...stockEffects, ...fdEffects] };
    }

    case "DELETE_INVESTMENT_TX": {
      const tid = action.payload;
      if (!tid) return s;
      // Remove only the requested real tx — never touch virtual (demerger/merger) txs directly
      const tx = s.investmentTx.find(t => t.id === tid);
      if (!tx || tx.invType === "demerger_virtual") return s; // can't delete virtual txs this way
      // Remove the real tx, then rebuild virtual txs from CAs against the updated real tx list
      const realTxs    = s.investmentTx.filter(t => t.id !== tid && t.invType !== "demerger_virtual");
      const virtualTxs = reapplyAllCAs(s.corporateActions, realTxs, s.holdings, s.corporateActionsMaster);
      const newTxs     = [...realTxs, ...virtualTxs];
      const { holdings: rebuilt } = rebuildHoldings(newTxs, []);
      const stockEffects = buildTradeBalanceEffects(newTxs, [], s.fxRates || {});
      const fdEffects = s.tradeBalanceEffects.filter(e => e.isFD);
      return { ...s, investmentTx: newTxs, holdings: rebuilt, tradeBalanceEffects: [...stockEffects, ...fdEffects] };
    }

    // Bulk delete multiple trades at once (Trade History multi-select)
    case "BULK_DELETE_INVESTMENT_TXS": {
      const ids = new Set(action.payload || []);
      if (ids.size === 0) return s;
      // Remove only real txs — never touch virtual txs directly
      const cleanRealTxs = s.investmentTx.filter(t => t.invType !== "demerger_virtual" && !ids.has(t.id));
      const virtualTxs   = reapplyAllCAs(s.corporateActions, cleanRealTxs, s.holdings, s.corporateActionsMaster);
      const newTxs       = [...cleanRealTxs, ...virtualTxs];
      if (newTxs.length === s.investmentTx.length && cleanRealTxs.length === s.investmentTx.filter(t=>t.invType!=="demerger_virtual").length) return s;
      const { holdings: rebuilt } = rebuildHoldings(newTxs, []);
      const stockEffects = buildTradeBalanceEffects(newTxs, [], s.fxRates || {});
      const fdEffects = s.tradeBalanceEffects.filter(e => e.isFD);
      return { ...s, investmentTx: newTxs, holdings: rebuilt, tradeBalanceEffects: [...stockEffects, ...fdEffects] };
    }

    // BULK_IMPORT_INVESTMENTS: atomically append many trades from a CSV import.
    // payload: { trades: itx[] }
    // Each itx must have accountId (investment) and sourceAccountId (bank).
    // Uses rebuildHoldings + buildTradeBalanceEffects — identical to delete/edit.
    // Single dispatch = single saveLocal = no stale-state or persistence issues.
    case "BULK_IMPORT_INVESTMENTS": {
      const { trades } = action.payload || {};
      if (!trades || trades.length === 0) return s;
      // Merge new trades with existing, preserving order by date
      const allTxs = [...s.investmentTx, ...trades].sort(
        (a, b) => new Date(a.date) - new Date(b.date)
      );
      // Rebuild holdings from scratch so FIFO is correct across old + new trades
      const { holdings: rebuilt } = rebuildHoldings(allTxs, []);
      // Rebuild all trade balance effects (stock effects only; FD effects preserved)
      const fdEffects    = s.tradeBalanceEffects.filter(e => e.isFD);
      const stockEffects = buildTradeBalanceEffects(allTxs, [], s.fxRates || {});
      return {
        ...s,
        investmentTx:        allTxs,
        holdings:            rebuilt,
        tradeBalanceEffects: [...stockEffects, ...fdEffects],
      };
    }

    // ── Fixed Deposits ────────────────────────────────────────────────────────
    case "ADD_FD": {
      const fd = action.payload;
      // Sync: deduct principal from source account via tradeBalanceEffect
      const fdEffects = [...s.tradeBalanceEffects];
      if (fd.sourceAccountId && parseFloat(fd.amount) > 0) {
        fdEffects.push({
          id: "fdeff_" + fd.id,
          accountId: fd.sourceAccountId,
          amount: parseFloat(fd.amount),
          sign: -1, // deduct from source
          tradeId: fd.id,
          date: fd.investedDate || new Date().toISOString().slice(0,10),
          isFD: true,
        });
      }
      return { ...s, fixedDeposits: [...(s.fixedDeposits||[]), fd], tradeBalanceEffects: fdEffects };
    }
    case "EDIT_FD": {
      const updated = action.payload;
      const old = (s.fixedDeposits||[]).find(f => f.id === updated.id);
      // Rebuild FD effects: remove old, add new
      let effs = s.tradeBalanceEffects.filter(e => e.tradeId !== updated.id);
      if (updated.sourceAccountId && parseFloat(updated.amount) > 0) {
        effs.push({
          id: "fdeff_" + updated.id,
          accountId: updated.sourceAccountId,
          amount: parseFloat(updated.amount),
          sign: -1,
          tradeId: updated.id,
          date: updated.investedDate || new Date().toISOString().slice(0,10),
          isFD: true,
        });
      }
      return { ...s, fixedDeposits: (s.fixedDeposits||[]).map(f => f.id===updated.id ? updated : f), tradeBalanceEffects: effs };
    }
    case "DELETE_FD": {
      const fdId = action.payload;
      // Remove tradeBalanceEffect for this FD
      const effs = s.tradeBalanceEffects.filter(e => e.tradeId !== fdId);
      return { ...s, fixedDeposits: (s.fixedDeposits||[]).filter(f => f.id !== fdId), tradeBalanceEffects: effs };
    }
    // CLOSE_FD: credit principal to selected account + record interest as income tx
    // FD is kept with status=closed for undo support (not deleted)
    case "CLOSE_FD": {
      const { fdId, incomeAccId, interestAmt, closeDate } = action.payload;
      const fd = (s.fixedDeposits||[]).find(f => f.id === fdId);
      if (!fd) return s;

      const targetAccId = incomeAccId || fd.sourceAccountId;
      const principal   = parseFloat(fd.amount) || 0;
      const interest    = parseFloat(interestAmt) || 0;

      const closeEffId  = "fdclose_" + fdId;
      const incTxId     = "fdint_" + fdId;

      // Keep original deduction effect (fdeff_*) — it records the opening deduction.
      // Add a close credit effect (fdclose_*) to credit the principal to the close account.
      // Net: source account stays -amount (opened), close account gets +amount (closed).
      // If source == close account: effects cancel → net 0 (money returned to same account).
      let effs = s.tradeBalanceEffects.filter(e => e.id !== closeEffId); // remove only stale close eff if any
      if (targetAccId && principal > 0) {
        effs.push({
          id:        closeEffId,
          accountId: targetAccId,
          amount:    principal,
          sign:      +1,
          tradeId:   fdId + "_close",
          date:      closeDate,
          isFD:      true,
        });
      }

      // Interest as income transaction
      const incTx = interest > 0 ? {
        id:         incTxId,
        type:       "income",
        amount:     interest,
        accountId:  targetAccId,
        categoryId: "ic_int",
        date:       closeDate,
        note:       "FD interest: " + (fd.name || "Fixed Deposit"),
        currency:   fd.currency || "INR",
        fdId:       fdId,
      } : null;

      // Mark FD as closed (keep it for undo); store close metadata
      const closedFd = {
        ...fd,
        status:         "closed",
        closeDate,
        closedAccId:    targetAccId,
        closedInterest: interest,
        closeEffId,
        incTxId:        incTx ? incTxId : null,
      };

      return {
        ...s,
        fixedDeposits:       (s.fixedDeposits||[]).map(f => f.id === fdId ? closedFd : f),
        tradeBalanceEffects: effs,
        transactions:        incTx ? [...s.transactions, incTx] : s.transactions,
      };
    }

    // UNDO_CLOSE_FD: reverses a closed FD back to active
    case "UNDO_CLOSE_FD": {
      const fdId = action.payload;
      const fd   = (s.fixedDeposits||[]).find(f => f.id === fdId);
      if (!fd || fd.status !== "closed") return s;

      // Remove the close credit effect only — fdeff_* (original deduction) stays
      // since we kept it during close. If fdeff_* is somehow missing, restore it.
      let effs = s.tradeBalanceEffects.filter(e => e.id !== fd.closeEffId);
      const hasOrigEff = effs.some(e => e.id === "fdeff_" + fdId);
      if (!hasOrigEff && fd.sourceAccountId && parseFloat(fd.amount) > 0) {
        effs.push({
          id:        "fdeff_" + fdId,
          accountId: fd.sourceAccountId,
          amount:    parseFloat(fd.amount),
          sign:      -1,
          tradeId:   fdId,
          date:      fd.investedDate || "",
          isFD:      true,
        });
      }

      // Remove the income transaction that was created for interest
      const newTxs = fd.incTxId
        ? s.transactions.filter(t => t.id !== fd.incTxId)
        : s.transactions;

      // Restore FD to active status — strip close metadata
      const { status, closeDate, closedAccId, closedInterest, closeEffId, incTxId, ...restoredFd } = fd;

      return {
        ...s,
        fixedDeposits:       (s.fixedDeposits||[]).map(f => f.id === fdId ? restoredFd : f),
        tradeBalanceEffects: effs,
        transactions:        newTxs,
      };
    }


    // ── Corporate Actions Master Table CRUD ─────────────────────────────────
    case "ADD_CA_MASTER": {
      const master = [...(s.corporateActionsMaster||[]), action.payload];
      return { ...s, corporateActionsMaster: master };
    }
    case "EDIT_CA_MASTER": {
      const master = (s.corporateActionsMaster||[]).map(m =>
        m.id === action.payload.id ? action.payload : m
      );
      return { ...s, corporateActionsMaster: master };
    }
    case "DELETE_CA_MASTER": {
      const masterId = action.payload;
      const master = (s.corporateActionsMaster||[]).filter(m => m.id !== masterId);

      // Also cascade-delete any applied corporateActions that were generated from this master entry
      const appliedCAs = (s.corporateActions||[]).filter(ca => ca._masterRef === masterId);

      // For each applied CA, run the full DELETE_CORPORATE_ACTION undo logic inline
      let cascadeState = { ...s, corporateActionsMaster: master };
      for (const ca of appliedCAs) {
        cascadeState = reducer(cascadeState, { type: "DELETE_CORPORATE_ACTION", payload: ca.id });
      }

      return cascadeState;
    }

    default: return s;
  }
}


// ─── buildCaFromMaster: convert a CA master record → a full CA payload ────────
// Used by auto-detection when a matching trade is found.
function buildCaFromMaster(master, state) {
  const { symbol, ca_type, record_date, ratio_from, ratio_to,
          parent_stock, new_stock, cost_split_parent_pct, cost_split_new_pct } = master;
  const id         = "ca_auto_" + master.id;
  const baseFields = { id, symbol, _masterRef: master.id, date: record_date, record_date, note: master.notes || "" };

  if (ca_type === "stock_split" || ca_type === "bonus") {
    const ratio = ratio_to && ratio_from ? ratio_to / ratio_from : 1;
    return { ...baseFields, action_type: ca_type, ratio };
  }
  if (ca_type === "reverse_split") {
    const ratio = ratio_from && ratio_to ? ratio_from / ratio_to : 1;
    return { ...baseFields, action_type: "reverse_split", ratio };
  }
  if (ca_type === "stock_name_change") {
    return { ...baseFields, action_type: "stock_name_change", new_symbol: new_stock.toUpperCase(), new_name: new_stock };
  }
  if (ca_type === "demerger_partial" || ca_type === "demerger_full") {
    const parentHolding = (state?.holdings||[]).find(h => h.symbol === symbol);
    const investmentTx  = state?.investmentTx || [];
    // Eligible shares via FIFO up to record_date
    const eligibleTxs = investmentTx.filter(tx => tx.symbol === symbol && tx.date <= record_date);
    let eligQty = 0;
    const lots = [];
    for (const tx of [...eligibleTxs].sort((a,b) => new Date(a.date)-new Date(b.date))) {
      if (tx.type === "buy") { lots.push({qty: parseFloat(tx.quantity)||0}); eligQty += parseFloat(tx.quantity)||0; }
      else if (tx.type === "sell") {
        let toConsume = parseFloat(tx.quantity)||0;
        for (const lot of lots) { const c = Math.min(lot.qty, toConsume); lot.qty -= c; toConsume -= c; eligQty -= c; }
      }
    }
    if (eligQty <= 0) return null;
    const accountId = parentHolding?.accountId || "";
    const parentPct  = parseFloat(cost_split_parent_pct) || 0;
    const newPct     = parseFloat(cost_split_new_pct)    || 0;
    const shareRatio = ratio_to && ratio_from ? ratio_to / ratio_from : 1;
    return {
      ...baseFields,
      action_type:    ca_type,
      demerger_type:  ca_type === "demerger_partial" ? "partial" : "full",
      eligible_shares: eligQty,
      result_stocks: [{
        symbol:      (new_stock || "").toUpperCase(),
        name:        new_stock || "",
        share_ratio: shareRatio,    // legacy field (ratio_to/ratio_from)
        ratio_from:  parseFloat(master.ratio_from) || 1,
        ratio_to:    parseFloat(master.ratio_to)   || 1,
        cost_pct:    newPct,
        accountId,
      }],
      // For partial demerger: parent retains cost_split_parent_pct of cost
    };
  }
  if (ca_type === "merger") {
    // Merger: source stock → target stock at swap ratio
    // ratio_from source shares → ratio_to target shares
    if (!new_stock) return null;
    const parentHolding = (state?.holdings||[]).find(h => h.symbol === symbol);
    if (!parentHolding) return null;
    return {
      ...baseFields,
      action_type:  "merger",
      ratio_from:   parseFloat(ratio_from) || 1,
      ratio_to:     parseFloat(ratio_to)   || 1,
      new_stock:    new_stock.toUpperCase(),
      accountId:    parentHolding.accountId || "",
    };
  }
  return null;
}

// ─── useCaAutoDetect: after trades added, check CA master for pending actions ──
// Returns: { pendingCAs, applyCA, dismissCA }
function useCaAutoDetect(state, dispatch) {
  const [pendingCAs, setPendingCAs] = useState([]);
  // dismissedIds = only for THIS session (e.g. user clicked X to dismiss temporarily)
  // Permanent suppression uses alreadyApplied (from DB wm_corporate_actions) — works across devices
  const [dismissedIds, setDismissedIds] = useState(new Set());

  // Core check function — scans CA master for symbols with eligible trades
  // Accepts optional currentState to avoid stale closure issues
  function checkForPendingCAs(symbols, currentState) {
    const s = currentState || state;
    const allSymbols = symbols && symbols.length > 0
      ? symbols
      : [...new Set((s?.investmentTx||[]).map(t => t.symbol).filter(Boolean))];

    if (allSymbols.length === 0) return;

    const alreadyApplied = new Set(
      (s?.corporateActions||[]).flatMap(ca => {
        const refs = [];
        if (ca._masterRef) refs.push(ca._masterRef);
        if (ca.id && ca.id.startsWith("ca_auto_")) refs.push(ca.id.replace("ca_auto_", ""));
        return refs;
      }).filter(Boolean)
    );
    const pending = (s?.corporateActionsMaster||[]).filter(m => {
      if (!allSymbols.includes(m.symbol)) return false;
      if (alreadyApplied.has(m.id)) return false;
      if (dismissedIds.has(m.id)) return false;
      const eligibleTrades = (s?.investmentTx||[]).filter(
        tx => tx.symbol === m.symbol && tx.date <= m.record_date && tx.type === "buy"
      );
      return eligibleTrades.length > 0;
    });
    if (pending.length > 0) setPendingCAs(prev => {
      const existingIds = new Set(prev.map(p => p.id));
      return [...prev, ...pending.filter(p => !existingIds.has(p.id))];
    });
  }

  // ── Scan whenever CA master OR trades change (catches post-load state) ─────
  const caMasterLen  = (state?.corporateActionsMaster||[]).length;
  const investTxLen  = (state?.investmentTx||[]).length;
  const appliedCaLen = (state?.corporateActions||[]).length;
  const [didInitialScan, setDidInitialScan] = useState(false);

  useEffect(() => {
    // Only scan once we have both CA master entries AND trades loaded
    if (caMasterLen > 0 && investTxLen > 0) {
      checkForPendingCAs(null, state);  // pass current state to avoid stale closure
      setDidInitialScan(true);
    }
  }, [caMasterLen, investTxLen, appliedCaLen]); // eslint-disable-line react-hooks/exhaustive-deps

  function applyCA(master) {
    const ca = buildCaFromMaster(master, state);
    if (ca) {
      dispatch({ type:"ADD_CORPORATE_ACTION", payload: ca });
      toast(`Corporate action applied: ${master.symbol} (${master.ca_type.replace(/_/g," ")})`);
    }
    // Remove from pending — alreadyApplied check (via DB corporateActions) will suppress on reload
    setPendingCAs(prev => prev.filter(p => p.id !== master.id));
    setDismissedIds(prev => new Set([...prev, master.id]));
  }

  function dismissCA(masterId) {
    // Session-only dismiss (X button) — banner won't reappear until next page load
    setPendingCAs(prev => prev.filter(p => p.id !== masterId));
    setDismissedIds(prev => new Set([...prev, masterId]));
  }

  return { pendingCAs, checkForPendingCAs, applyCA, dismissCA };
}

// ─── TOAST CONTEXT ────────────────────────────────────────────────────────────
// Global toast system — components call window.__toast(msg, type)
function useToastSystem() {
  const [toasts, setToasts] = useState([]);

  const addToast = useCallback((message, type="success") => {
    const id = uid();
    setToasts(prev => [...prev, { id, message, type }]);
    setTimeout(() => {
      setToasts(prev => prev.filter(t => t.id !== id));
    }, 2500);
  }, []);

  // Expose globally so any component can call window.__toast(msg, type)
  useEffect(() => { window.__toast = addToast; }, [addToast]);

  return toasts;
}

// ─── TOAST RENDERER ──────────────────────────────────────────────────────────
function ToastContainer({ toasts }) {
  return (
    <div style={{
      position:"fixed", top:16, right:16, zIndex:9999,
      display:"flex", flexDirection:"column", gap:8,
      pointerEvents:"none",
    }}>
      {toasts.map(t => (
        <div key={t.id} style={{
          background: t.type==="error" ? "#1A0A0A" : "#120F00",
          border: `1px solid ${t.type==="error" ? "#FF4444" : "#FFD700"}`,
          color: t.type==="error" ? "#B91C1C" : "#D4A017",
          padding:"12px 18px", borderRadius:12, fontSize:14, fontWeight:600,
          boxShadow:"0 4px 20px rgba(0,0,0,0.12)",
          animation:"toastIn 0.25s ease",
          maxWidth:320, wordBreak:"break-word",
        }}>
          {t.type==="error" ? "⚠️" : "✅"} {t.message}
        </div>
      ))}
      <style>{`
        @keyframes toastIn {
          from { opacity:0; transform:translateY(-8px) scale(0.97); }
          to   { opacity:1; transform:translateY(0) scale(1); }
        }
        @keyframes spin {
          to { transform: rotate(360deg); }
        }
      `}</style>
    </div>
  );
}

const toast = (msg, type="success") => window.__toast?.(msg, type);

// ─── TINY COMPONENTS ─────────────────────────────────────────────────────────
function Card({ children, style={} }) {
  return <div style={{background:"#161616",borderRadius:16,padding:20,boxShadow:"0 2px 16px rgba(0,0,0,0.5)",border:"1px solid #1F2937",...style}}>{children}</div>;
}

// Modal: renders as centered dialog on desktop, bottom sheet on mobile
function Modal({ title, onClose, children }) {
  useEffect(() => {
    document.body.style.overflow = "hidden";
    return () => { document.body.style.overflow = ""; };
  }, []);
  return (
    <div
      onClick={e => e.target===e.currentTarget && onClose()}
      style={{
        position:"fixed", inset:0, zIndex:1000,
        background:"rgba(0,0,0,0.82)", backdropFilter:"blur(6px)",
        display:"flex", alignItems:"flex-end", justifyContent:"center",
      }}
    >
      <div style={{
        background:"#161616", borderRadius:"20px 20px 0 0",
        width:"100%", maxWidth:560,
        maxHeight:"92dvh", overflowY:"auto",
        boxShadow:"0 -8px 60px rgba(0,0,0,0.7)",border:"1px solid #1F2937",borderBottom:"none",
        paddingBottom:"env(safe-area-inset-bottom,12px)",
      }}>
        {/* Drag handle */}
        <div style={{display:"flex",justifyContent:"center",padding:"10px 0 4px"}}>
          <div style={{width:36,height:4,borderRadius:2,background:"#2A2A2A"}}/>
        </div>
        <div style={{padding:"4px 20px 0",display:"flex",justifyContent:"space-between",alignItems:"center"}}>
          <h3 style={{margin:0,fontSize:17,fontWeight:700,color:"#FFFFFF"}}>{title}</h3>
          <button onClick={onClose} style={{
            border:"none", background:"#1E1E1E", borderRadius:8,
            width:40, height:40, cursor:"pointer", fontSize:20,
            display:"flex", alignItems:"center", justifyContent:"center", flexShrink:0,
          }}>×</button>
        </div>
        <div style={{padding:"12px 20px 20px"}}>{children}</div>
      </div>
    </div>
  );
}

function Field({ label, children, note }) {
  return (
    <div style={{marginBottom:16}}>
      {label && <label style={{display:"block",fontSize:12,fontWeight:600,color:"#6B6B6B",marginBottom:6,textTransform:"uppercase",letterSpacing:"0.05em"}}>{label}</label>}
      {children}
      {note && <div style={{fontSize:11,color:"#6B6B6B",marginTop:4}}>{note}</div>}
    </div>
  );
}

// inputStyle: font-size 16px prevents iOS zoom on focus
const inputStyle = {
  width:"100%", border:"1.5px solid #333333", borderRadius:10,
  padding:"11px 14px", fontSize:16, outline:"none",
  boxSizing:"border-box", fontFamily:"inherit", WebkitAppearance:"none",
  background:"#1E1E1E", color:"#FFFFFF",
};

function Inp({ label, note, ...props }) {
  return (
    <Field label={label} note={note}>
      <input {...props} style={{...inputStyle,...props.style}}
        onFocus={e=>{e.target.style.borderColor="#F5C518";e.target.style.boxShadow="0 0 0 3px rgba(245,197,24,0.15)"}}
        onBlur={e=>{e.target.style.borderColor="#2A2A2A";e.target.style.boxShadow="none"}} />
    </Field>
  );
}

function Sel({ label, children, note, ...props }) {
  return (
    <Field label={label} note={note}>
      <select {...props} style={{...inputStyle,background:"#161616",cursor:"pointer",...props.style}}>{children}</select>
    </Field>
  );
}

// Toggle (boolean switch)
function Toggle({ label, checked, onChange, note }) {
  return (
    <Field label={label} note={note}>
      <button
        onClick={() => onChange(!checked)}
        style={{
          display:"flex", alignItems:"center", gap:10,
          background:"none", border:"none", cursor:"pointer", padding:0,
        }}
      >
        <div style={{
          width:44, height:26, borderRadius:13,
          background: checked ? "#F5C518" : "#2A2A2A",
          position:"relative", transition:"background 0.2s", flexShrink:0,
        }}>
          <div style={{
            position:"absolute", top:3, left: checked ? 21 : 3,
            width:20, height:20, borderRadius:"50%", background:"#161616",
            transition:"left 0.2s", boxShadow:"0 1px 4px rgba(0,0,0,0.2)",
          }}/>
        </div>
        <span style={{fontSize:14, color: checked ? "#F5C518" : "#6B6B6B", fontWeight:600}}>
          {checked ? "Yes" : "No"}
        </span>
      </button>
    </Field>
  );
}

const btnVariants = {
  primary: d => ({background:d?"#2A2A2A":"linear-gradient(135deg,#F5C518,#D4A017)",color:d?"#555555":"#0D0D0D",border:"none",boxShadow:d?"none":"0 2px 12px rgba(245,197,24,0.3)"}),
  ghost:   ()  => ({background:"transparent",color:"#A3A3A3",border:"1.5px solid #333333"}),
  danger:  ()  => ({background:"#1A0A0A",color:"#FF4444",border:"1.5px solid #3D0000"}),
  success: ()  => ({background:"#22C55E",color:"#0D0D0D",border:"none",fontWeight:700,boxShadow:"0 2px 12px rgba(34,197,94,0.3)"}),
  warning: ()  => ({background:"#1E1E1E",color:"#F5C518",border:"1px solid #2A1800"}),
};
const btnSizes = {
  sm: { padding:"9px 16px", fontSize:13 },
  md: { padding:"13px 20px", fontSize:14 },
};
function Btn({ children, onClick, variant="primary", size="md", disabled=false, style={} }) {
  return (
    <button onClick={disabled?undefined:onClick} disabled={disabled}
      style={{
        borderRadius:10, fontWeight:600, cursor:disabled?"not-allowed":"pointer",
        fontFamily:"inherit", transition:"all 0.15s",
        ...btnVariants[variant](disabled), ...btnSizes[size], ...style,
      }}>
      {children}
    </button>
  );
}

function Badge({ children, color, bg }) {
  return <span style={{background:bg,color,fontSize:11,padding:"2px 8px",borderRadius:20,fontWeight:600}}>{children}</span>;
}

// Two-column button row (full width on mobile)
function BtnRow({ children }) {
  return <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10,marginTop:10}}>{children}</div>;
}

// ─── AUTH SCREEN ──────────────────────────────────────────────────────────────
function AuthScreen({ onAuth }) {
  const [mode,setMode]         = useState("login");
  const [email,setEmail]       = useState("");
  const [password,setPassword] = useState("");
  const [loading,setLoading]   = useState(false);
  const [err,setErr]           = useState("");
  const [msg,setMsg]           = useState("");

  async function submit() {
    if (!email||!password) { setErr("Fill in all fields."); return; }
    setLoading(true); setErr(""); setMsg("");
    try {
      if (mode==="signup") {
        const {error:e} = await supabase.auth.signUp({email,password});
        if (e) throw e;
        setMsg("✅ Account created! You can now log in.");
        setMode("login");
      } else {
        const {data,error:e} = await supabase.auth.signInWithPassword({email,password});
        if (e) throw e;
        onAuth(data.user);
      }
    } catch(e) { setErr(e.message||"Something went wrong."); }
    setLoading(false);
  }
  async function forgot() {
    if (!email) { setErr("Enter your email first."); return; }
    setLoading(true);
    const {error:e} = await supabase.auth.resetPasswordForEmail(email);
    if (e) setErr(e.message); else setMsg("✅ Reset email sent!");
    setLoading(false);
  }

  return (
    <div style={{minHeight:"100vh",background:"linear-gradient(135deg,#1A1400,#111111,#0D0D0D)",display:"flex",alignItems:"center",justifyContent:"center",padding:16}}>
      <div style={{background:"#161616",borderRadius:24,padding:36,width:"100%",maxWidth:400,boxShadow:"0 32px 80px rgba(0,0,0,0.3)"}}>
        <div style={{textAlign:"center",marginBottom:32}}>
          <img src={LOGO_IMG} alt="Rakesh's Finance" style={{height:100,width:"auto",maxWidth:"100%",objectFit:"contain",margin:"0 auto 16px",display:"block"}} />
          <p style={{margin:"4px 0 0",color:"#6B6B6B",fontSize:13}}>Your personal finance tracker</p>
        </div>
        <div style={{display:"flex",marginBottom:24,background:"#1E1E1E",borderRadius:12,padding:4}}>
          {["login","signup"].map(m=>(
            <button key={m} onClick={()=>{setMode(m);setErr("");setMsg("");}}
              style={{flex:1,padding:"8px",borderRadius:9,border:"none",background:mode===m?"#161616":"transparent",color:mode===m?"#FFFFFF":"#6B6B6B",fontWeight:700,fontSize:14,cursor:"pointer",fontFamily:"inherit",boxShadow:mode===m?"0 1px 4px rgba(0,0,0,0.1)":"none"}}>
              {m==="login"?"Log In":"Sign Up"}
            </button>
          ))}
        </div>
        {err&&<div style={{background:"#1A0A0A",border:"1px solid #2A0F0F",borderRadius:10,padding:"10px 14px",marginBottom:16,fontSize:13,color:"#B91C1C"}}>{err}</div>}
        {msg&&<div style={{background:"#120F00",border:"1px solid #1A2A1A",borderRadius:10,padding:"10px 14px",marginBottom:16,fontSize:13,color:"#D4A017"}}>{msg}</div>}
        <Inp label="Email"    type="email"    value={email}    onChange={e=>setEmail(e.target.value)}    placeholder="you@example.com" />
        {mode!=="forgot"&&<Inp label="Password" type="password" value={password} onChange={e=>setPassword(e.target.value)} placeholder="••••••••" />}
        <Btn onClick={submit} disabled={loading} style={{width:"100%",marginBottom:12}}>
          {loading?"Please wait…":mode==="login"?"Log In":"Create Account"}
        </Btn>
        {mode==="login"&&<button onClick={()=>{setMode("forgot");setErr("");}} style={{background:"none",border:"none",color:"#F5C518",fontSize:13,cursor:"pointer",fontFamily:"inherit",width:"100%",textAlign:"center"}}>Forgot password?</button>}
        {mode==="forgot"&&<>
          <Btn onClick={forgot} disabled={loading} variant="ghost" style={{width:"100%",marginBottom:8}}>Send Reset Email</Btn>
          <button onClick={()=>setMode("login")} style={{background:"none",border:"none",color:"#F5C518",fontSize:13,cursor:"pointer",fontFamily:"inherit",width:"100%",textAlign:"center"}}>Back to login</button>
        </>}
      </div>
    </div>
  );
}

// ─── CREDIT CARD SETTINGS MODAL ───────────────────────────────────────────────
// Separate modal for CC-specific settings (bill date, cashback tiers, etc.)
function CreditCardSettingsModal({ acc, onClose, onSave }) {
  const [billDay,     setBillDay]     = useState(acc.billDay     || 1);
  const [dueDay,      setDueDay]      = useState(acc.dueDay      || 20);
  const [cbTiming,    setCbTiming]    = useState(acc.cbTiming    || "before"); // before | after
  const [cbType,      setCbType]      = useState(acc.cbType      || "unlimited"); // unlimited | limited
  const [cbTiers,     setCbTiers]     = useState(acc.cbTiers     || [{ pct:"1", limit:"" }]);
  const [cbWalletId,  setCbWalletId]  = useState(acc.cbWalletId  || "");
  const [cbCreditSelf,setCbCreditSelf]= useState(acc.cbCreditSelf !== false); // default: card itself

  const { accounts = [] } = acc._stateRef || {};
  const nonCCAccounts = accounts.filter(a => !a.disabled && a.account_type !== "cat_cc" && a.categoryId !== "cat_cc" && !a.isCreditCard);

  function addTier()   { setCbTiers(t => [...t, { pct:"", limit:"" }]); }
  function delTier(i)  { setCbTiers(t => t.filter((_,j) => j!==i)); }
  function updTier(i, key, val) {
    setCbTiers(t => t.map((tier, j) => j===i ? {...tier,[key]:val} : tier));
  }

  function save() {
    const validTiers = cbTiers.filter(t => parseFloat(t.pct)>0).map(t => ({
      pct: parseFloat(t.pct),
      limit: cbType==="limited" ? parseFloat(t.limit)||0 : null,
    }));
    onSave({
      ...acc,
      isCreditCard: true,
      billDay: parseInt(billDay)||1,
      dueDay:  parseInt(dueDay) ||20,
      cbTiming,
      cbType,
      cbTiers: validTiers,
      cbCreditSelf: cbCreditSelf,
      cbWalletId: cbCreditSelf ? "" : (cbWalletId || ""),
    });
    toast("Credit card settings saved");
    onClose();
  }

  return (
    <Modal title="Credit Card Settings" onClose={onClose}>
      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:12}}>
        <Inp label="Bill Generation Day" type="number" min={1} max={31}
             value={billDay} onChange={e=>setBillDay(e.target.value)} note="1–31" />
        <Inp label="Payment Due Day" type="number" min={1} max={31}
             value={dueDay} onChange={e=>setDueDay(e.target.value)} note="1–31" />
      </div>

      <Field label="Cashback Credit Timing">
        <div style={{display:"flex",gap:8}}>
          {[["before","Before Bill Date"],["after","After Bill Date"]].map(([v,l])=>(
            <button key={v} onClick={()=>setCbTiming(v)} style={{
              flex:1, padding:"10px 8px", borderRadius:10, cursor:"pointer",
              border:`2px solid ${cbTiming===v?"#F5C518":"#2A2A2A"}`,
              background:cbTiming===v?"#1E1E1E":"#161616",
              color:cbTiming===v?"#F5C518":"#6B6B6B",
              fontWeight:600, fontSize:13, fontFamily:"inherit",
            }}>{l}</button>
          ))}
        </div>
      </Field>

      <Field label="Cashback Credited To">
        <div style={{display:"flex",gap:8,marginBottom:cbCreditSelf?0:10}}>
          <button onClick={()=>setCbCreditSelf(true)}
            style={{flex:1,padding:"10px 8px",borderRadius:10,cursor:"pointer",fontFamily:"inherit",fontWeight:600,fontSize:13,
              border:`2px solid ${cbCreditSelf?"#F5C518":"#2A2A2A"}`,
              background:cbCreditSelf?"#1E1E1E":"#161616",color:cbCreditSelf?"#F5C518":"#6B6B6B"}}>
            💳 This Card Itself
          </button>
          <button onClick={()=>setCbCreditSelf(false)}
            style={{flex:1,padding:"10px 8px",borderRadius:10,cursor:"pointer",fontFamily:"inherit",fontWeight:600,fontSize:13,
              border:`2px solid ${!cbCreditSelf?"#F5C518":"#2A2A2A"}`,
              background:!cbCreditSelf?"#1E1E1E":"#161616",color:!cbCreditSelf?"#F5C518":"#6B6B6B"}}>
            🏦 Another Account
          </button>
        </div>
        {!cbCreditSelf && (
          <Sel label="" value={cbWalletId} onChange={e=>setCbWalletId(e.target.value)}
               note="Account where cashback will be credited">
            <option value="">Select account…</option>
            {nonCCAccounts.map(a=><option key={a.id} value={a.id}>{a.icon} {a.name}</option>)}
          </Sel>
        )}
      </Field>

      <Field label="Cashback Type">
        <div style={{display:"flex",gap:8}}>
          {[["unlimited","Unlimited"],["limited","Limited (Cap)"]].map(([v,l])=>(
            <button key={v} onClick={()=>setCbType(v)} style={{
              flex:1, padding:"10px 8px", borderRadius:10, cursor:"pointer",
              border:`2px solid ${cbType===v?"#F5C518":"#2A2A2A"}`,
              background:cbType===v?"#1E1E1E":"#161616",
              color:cbType===v?"#F5C518":"#6B6B6B",
              fontWeight:600, fontSize:13, fontFamily:"inherit",
            }}>{l}</button>
          ))}
        </div>
      </Field>

      <Field label="Cashback Tiers" note="Define percentage tiers for this card">
        {cbTiers.map((tier, i) => (
          <div key={i} style={{display:"grid",gridTemplateColumns:cbType==="limited"?"1fr 1fr 32px":"1fr 32px",gap:8,marginBottom:8,alignItems:"end"}}>
            <Inp label={i===0?"Percentage (%)":""} type="number" min={0} max={100} step="0.1"
                 value={tier.pct} onChange={e=>updTier(i,"pct",e.target.value)}
                 placeholder="e.g. 10" style={{marginBottom:0}} />
            {cbType==="limited"&&(
              <Inp label={i===0?"Cashback Limit (₹)":""} type="number" min={0}
                   value={tier.limit} onChange={e=>updTier(i,"limit",e.target.value)}
                   placeholder="e.g. 1500" style={{marginBottom:0}} />
            )}
            <button onClick={()=>delTier(i)} style={{
              width:32, height:42, borderRadius:8, border:"1px solid #2A0F0F",
              background:"#1A0A0A", color:"#FF4444", cursor:"pointer", fontSize:16,
              display:"flex", alignItems:"center", justifyContent:"center", flexShrink:0,
            }}>×</button>
          </div>
        ))}
        <Btn variant="ghost" size="sm" onClick={addTier} style={{width:"100%",marginTop:4}}>+ Add Tier</Btn>
      </Field>

      <BtnRow>
        <Btn variant="ghost" onClick={onClose}>Cancel</Btn>
        <Btn onClick={save}>Save Settings</Btn>
      </BtnRow>
    </Modal>
  );
}

// ─── ACCOUNT MODAL  (add + edit) ─────────────────────────────────────────────
function AccountModal({ state, onClose, onSave, editAcc }) {
  const isEdit    = !!editAcc;
  const cats      = state?.accountCategories || DEFAULT.accountCategories;
  const icons     = ["🏦","💵","💳","📱","📈","📊","💰","🏧","🪙","💼","🏠","✈️","🎮","🔐","💎"];

  const [name,          setName]          = useState(editAcc?.name          || "");
  const [catId,         setCatId]         = useState(editAcc?.categoryId    || cats[0]?.id||"");
  const [cur,           setCur]           = useState(editAcc?.currency       || "INR");
  const [icon,          setIcon]          = useState(editAcc?.icon           || "🏦");
  const [opening,       setOpening]       = useState(editAcc?.openingBalance != null ? String(editAcc.openingBalance) : "");
  const [inclNW,        setInclNW]        = useState(editAcc?.includeInNetWorth ?? true);
  const [showCCSettings,setShowCCSettings]= useState(false);

  // Determine if this account is CC type based on category's isCreditCardType flag
  const selCat    = cats.find(c => c.id===catId);
  const isCCCat   = !!selCat?.isCreditCardType;

  function save(ccOverrides={}) {
    if (!name.trim()) return;
    const cat = cats.find(c=>c.id===catId);
    const ob  = parseFloat(opening)||0;
    const base = {
      name:name.trim(), categoryId:catId, account_type:catId, currency:cur, icon,
      color:cat?.color||"#6B6B6B", openingBalance:ob,
      includeInNetWorth:inclNW, include_in_networth:inclNW, disabled:false,
    };
    if (isEdit) {
      onSave({...editAcc, ...base, ...ccOverrides});
    } else {
      onSave({id:uid(), ...base, ...ccOverrides});
    }
    toast(isEdit ? "Account updated" : "Account added");
    onClose();
  }

  // If CC category, open CC settings and save from there
  function handleSave() {
    if (isCCCat || editAcc?.isCreditCard) {
      setShowCCSettings(true);
    } else {
      save({ isCreditCard:false });
    }
  }

  return (
    <>
      <Modal title={isEdit?"Edit Account":"Add Account"} onClose={onClose}>
        <Sel label="Account Type" value={catId} onChange={e=>setCatId(e.target.value)}>
          {cats.map(c=><option key={c.id} value={c.id}>{c.icon} {c.name}</option>)}
        </Sel>
        <Inp label="Account Name" value={name} onChange={e=>setName(e.target.value)} placeholder="e.g. SBI Savings, Zerodha…" />
        <Sel label="Currency" value={cur} onChange={e=>setCur(e.target.value)}>
          {CURRENCIES.map(c=><option key={c.code} value={c.code}>{c.symbol} {c.code} — {c.name}</option>)}
        </Sel>
        <Inp label={`Opening Balance (${cur})`} type="number" value={opening}
             onChange={e=>setOpening(e.target.value)} placeholder="0.00" />
        <Toggle label="Include in Net Worth?" checked={inclNW} onChange={setInclNW}
                note={isCCCat ? "CC payable balance will be deducted from net worth" : "Asset balance counted toward net worth"} />
        <Field label="Icon">
          <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
            {icons.map(ic=>(
              <button key={ic} onClick={()=>setIcon(ic)}
                style={{width:40,height:40,borderRadius:10,border:`2px solid ${icon===ic?"#F5C518":"#2A2A2A"}`,background:icon===ic?"#1E1E1E":"#161616",fontSize:20,cursor:"pointer"}}>{ic}</button>
            ))}
          </div>
        </Field>
        <BtnRow>
          <Btn variant="ghost" onClick={onClose}>Cancel</Btn>
          <Btn onClick={handleSave}>{isEdit?"Save Changes":(isCCCat?"Next: CC Settings":"Add Account")}</Btn>
        </BtnRow>
      </Modal>

      {showCCSettings && (
        <CreditCardSettingsModal
          acc={{
            ...(editAcc || {}),
            name:name.trim(), categoryId:catId, currency:cur, icon,
            color:cats.find(c=>c.id===catId)?.color||"#FF4444",
            openingBalance:parseFloat(opening)||0,
            includeInNetWorth:inclNW, include_in_networth:inclNW,
            _stateRef:{ accounts: state?.accounts||[] },
          }}
          onClose={()=>setShowCCSettings(false)}
          onSave={ccAcc => {
            // Strip internal _stateRef before saving
            const { _stateRef, ...clean } = ccAcc;
            save(clean);
          }}
        />
      )}
    </>
  );
}

// ─── ACCOUNT TYPE MODAL ───────────────────────────────────────────────────────
