// ─── TX CATEGORY MODAL ────────────────────────────────────────────────────────
// Supports: add/delete top-level categories + manage sub-categories per parent.
// subCategories[] stored on each category object; null-safe everywhere.
// Category & sub-category manager with edit support
function TxCatModal({ kind, categories, onClose, onAdd, onDelete, onUpdate }) {
  const icons = ["🏷️","🍽️","🚗","🛍️","⚡","🏥","🎬","📚","🤝","💼","💻","🏢","🏦","📊","🏠","↩️","✈️","🎮","💊","🐾","🎁","⛽","📱","🔧","🎵","🏋️","☕","🛒","🎓"];
  const [name,      setName]      = useState("");
  const [icon,      setIcon]      = useState("🏷️");
  const [editId,    setEditId]    = useState(null);   // category id being edited
  const [editName,  setEditName]  = useState("");
  const [editIcon,  setEditIcon]  = useState("🏷️");
  const [subMgr,    setSubMgr]    = useState(null);
  const [subName,   setSubName]   = useState("");
  const [subIcon,   setSubIcon]   = useState("🏷️");
  const [subEditId, setSubEditId] = useState(null);   // sub id being edited
  const [subEditName,setSubEditName]=useState("");
  const [subEditIcon,setSubEditIcon]=useState("🏷️");

  function addMain() {
    if (!name.trim()) return;
    onAdd({ id:uid(), name:name.trim(), icon, subCategories:[] });
    setName(""); setIcon("🏷️");
    toast("Category added");
  }
  function startEditMain(c) { setEditId(c.id); setEditName(c.name); setEditIcon(c.icon||"🏷️"); }
  function saveEditMain(c) {
    onUpdate({...c, name:editName.trim()||c.name, icon:editIcon});
    setEditId(null); toast("Category updated");
  }

  function openSubs(cat) { setSubMgr(cat); setSubName(""); setSubIcon("🏷️"); setSubEditId(null); }
  function closeSubs()   { setSubMgr(null); setSubEditId(null); }

  function addSub() {
    if (!subName.trim()) return;
    const updated = { ...subMgr, subCategories:[...(subMgr.subCategories||[]), {id:uid(),name:subName.trim(),icon:subIcon}] };
    onUpdate(updated); setSubMgr(updated); setSubName(""); setSubIcon("🏷️");
    toast("Sub-category added");
  }
  function delSub(subId) {
    const updated = { ...subMgr, subCategories:(subMgr.subCategories||[]).filter(s=>s.id!==subId) };
    onUpdate(updated); setSubMgr(updated); toast("Removed");
  }
  function startEditSub(s) { setSubEditId(s.id); setSubEditName(s.name); setSubEditIcon(s.icon||"🏷️"); }
  function saveEditSub() {
    const updated = { ...subMgr, subCategories:(subMgr.subCategories||[]).map(s=>
      s.id===subEditId ? {...s, name:subEditName.trim()||s.name, icon:subEditIcon} : s
    )};
    onUpdate(updated); setSubMgr(updated); setSubEditId(null); toast("Sub-category updated");
  }

  // ── Sub-category manager view ──────────────────────────────────────────────
  if (subMgr) {
    const live = categories.find(c=>c.id===subMgr.id) || subMgr;
    return (
      <Modal title={`${live.icon} ${live.name} — Sub-categories`} onClose={onClose}>
        <button onClick={closeSubs} style={{background:"none",border:"none",color:"#F5C518",fontWeight:600,fontSize:13,cursor:"pointer",fontFamily:"inherit",marginBottom:14,padding:0}}>← Back</button>
        {(live.subCategories||[]).length===0&&<div style={{fontSize:13,color:"#6B6B6B",marginBottom:14}}>No sub-categories yet.</div>}
        {(live.subCategories||[]).map(s=>(
          <div key={s.id} style={{borderBottom:"1px solid #222222",padding:"8px 0"}}>
            {subEditId===s.id ? (
              <div>
                <div style={{display:"grid",gridTemplateColumns:"1fr auto",gap:8,marginBottom:6}}>
                  <input value={subEditName} onChange={e=>setSubEditName(e.target.value)}
                    style={{padding:"6px 10px",border:"1px solid #1A1A2A",borderRadius:8,fontSize:13,fontFamily:"inherit"}}/>
                  <button onClick={saveEditSub} style={{padding:"6px 12px",borderRadius:8,border:"none",background:"#F5C518",color:"#161616",fontWeight:700,cursor:"pointer",fontFamily:"inherit",fontSize:12}}>Save</button>
                </div>
                <div style={{display:"flex",gap:4,flexWrap:"wrap",marginBottom:4}}>
                  {icons.map(ic=><button key={ic} onClick={()=>setSubEditIcon(ic)} style={{width:30,height:30,borderRadius:7,border:`2px solid ${subEditIcon===ic?"#F5C518":"#2A2A2A"}`,background:subEditIcon===ic?"#1E1E1E":"#161616",fontSize:14,cursor:"pointer"}}>{ic}</button>)}
                </div>
                <button onClick={()=>setSubEditId(null)} style={{fontSize:11,color:"#6B6B6B",background:"none",border:"none",cursor:"pointer",fontFamily:"inherit"}}>Cancel</button>
              </div>
            ) : (
              <div style={{display:"flex",alignItems:"center",gap:8}}>
                <div style={{width:30,height:30,borderRadius:8,background:"#1E1E1E",display:"flex",alignItems:"center",justifyContent:"center",fontSize:16,flexShrink:0}}>{s.icon}</div>
                <span style={{flex:1,fontWeight:600,fontSize:13}}>{s.name}</span>
                <button onClick={()=>startEditSub(s)} style={{fontSize:11,padding:"3px 8px",borderRadius:7,border:"1.5px solid #2A2A2A",background:"#161616",cursor:"pointer",fontFamily:"inherit"}}>✏️</button>
                <button onClick={()=>delSub(s.id)} style={{fontSize:11,padding:"3px 8px",borderRadius:7,border:"1px solid #2A0F0F",background:"#1A0A0A",color:"#FF4444",cursor:"pointer",fontFamily:"inherit",fontWeight:700}}>×</button>
              </div>
            )}
          </div>
        ))}
        <div style={{borderTop:"1px solid #222222",paddingTop:14,marginTop:8}}>
          <div style={{fontSize:12,fontWeight:600,color:"#6B6B6B",marginBottom:8,textTransform:"uppercase",letterSpacing:"0.05em"}}>Add Sub-category</div>
          <Inp label="Name" value={subName} onChange={e=>setSubName(e.target.value)} placeholder="e.g. Breakfast, Metro…" />
          <Field label="Icon"><div style={{display:"flex",gap:5,flexWrap:"wrap"}}>{icons.map(ic=><button key={ic} onClick={()=>setSubIcon(ic)} style={{width:32,height:32,borderRadius:8,border:`2px solid ${subIcon===ic?"#F5C518":"#2A2A2A"}`,background:subIcon===ic?"#1E1E1E":"#161616",fontSize:15,cursor:"pointer"}}>{ic}</button>)}</div></Field>
          <Btn onClick={addSub} style={{width:"100%"}}>+ Add Sub-category</Btn>
        </div>
      </Modal>
    );
  }

  // ── Main list view ─────────────────────────────────────────────────────────
  return (
    <Modal title={`${kind==="expense"?"Expense":"Income"} Categories`} onClose={onClose}>
      <div style={{marginBottom:16}}>
        {categories.length===0&&<div style={{fontSize:13,color:"#6B6B6B",marginBottom:10}}>None yet.</div>}
        {categories.map(c=>(
          <div key={c.id} style={{borderBottom:"1px solid #222222",padding:"8px 0"}}>
            {editId===c.id ? (
              <div>
                <div style={{display:"grid",gridTemplateColumns:"1fr auto",gap:8,marginBottom:6}}>
                  <input value={editName} onChange={e=>setEditName(e.target.value)}
                    style={{padding:"6px 10px",border:"1px solid #1A1A2A",borderRadius:8,fontSize:13,fontFamily:"inherit"}}/>
                  <button onClick={()=>saveEditMain(c)} style={{padding:"6px 12px",borderRadius:8,border:"none",background:"#F5C518",color:"#161616",fontWeight:700,cursor:"pointer",fontFamily:"inherit",fontSize:12}}>Save</button>
                </div>
                <div style={{display:"flex",gap:4,flexWrap:"wrap",marginBottom:4}}>
                  {icons.map(ic=><button key={ic} onClick={()=>setEditIcon(ic)} style={{width:30,height:30,borderRadius:7,border:`2px solid ${editIcon===ic?"#F5C518":"#2A2A2A"}`,background:editIcon===ic?"#1E1E1E":"#161616",fontSize:14,cursor:"pointer"}}>{ic}</button>)}
                </div>
                <button onClick={()=>setEditId(null)} style={{fontSize:11,color:"#6B6B6B",background:"none",border:"none",cursor:"pointer",fontFamily:"inherit"}}>Cancel</button>
              </div>
            ) : (
              <div style={{display:"flex",alignItems:"center",gap:8}}>
                <div style={{width:34,height:34,borderRadius:9,background:"#1E1E1E",display:"flex",alignItems:"center",justifyContent:"center",fontSize:18,flexShrink:0}}>{c.icon}</div>
                <div style={{flex:1,minWidth:0}}>
                  <div style={{fontWeight:600,fontSize:14}}>{c.name}</div>
                  {(c.subCategories||[]).length>0&&<div style={{fontSize:11,color:"#6B6B6B"}}>{c.subCategories.length} sub-{c.subCategories.length===1?"category":"categories"}</div>}
                </div>
                <button onClick={()=>openSubs(c)} style={{fontSize:12,padding:"4px 10px",borderRadius:8,border:"1px solid #1A1A2A",background:"#1E1E1E",color:"#F5C518",cursor:"pointer",fontFamily:"inherit",fontWeight:600,flexShrink:0}}>Sub</button>
                <button onClick={()=>startEditMain(c)} style={{fontSize:12,padding:"4px 8px",borderRadius:8,border:"1.5px solid #2A2A2A",background:"#161616",cursor:"pointer",fontFamily:"inherit",fontWeight:600,flexShrink:0}}>✏️</button>
                <button onClick={()=>onDelete(c.id)} style={{fontSize:12,padding:"4px 8px",borderRadius:8,border:"1px solid #2A0F0F",background:"#1A0A0A",color:"#FF4444",cursor:"pointer",fontFamily:"inherit",fontWeight:600,flexShrink:0}}>×</button>
              </div>
            )}
          </div>
        ))}
      </div>
      <div style={{borderTop:"1px solid #222222",paddingTop:16}}>
        <div style={{fontSize:12,fontWeight:600,color:"#6B6B6B",marginBottom:8,textTransform:"uppercase",letterSpacing:"0.05em"}}>Add Category</div>
        <Inp label="Name" value={name} onChange={e=>setName(e.target.value)} placeholder={kind==="expense"?"e.g. Gym, Travel…":"e.g. Bonus, Gift…"} />
        <Field label="Icon"><div style={{display:"flex",gap:5,flexWrap:"wrap"}}>{icons.map(ic=><button key={ic} onClick={()=>setIcon(ic)} style={{width:32,height:32,borderRadius:8,border:`2px solid ${icon===ic?"#F5C518":"#2A2A2A"}`,background:icon===ic?"#1E1E1E":"#161616",fontSize:15,cursor:"pointer"}}>{ic}</button>)}</div></Field>
        <BtnRow><Btn variant="ghost" onClick={onClose}>Close</Btn><Btn onClick={addMain}>Add</Btn></BtnRow>
      </div>
    </Modal>
  );
}

